\label{def:complex-Kill-eq}
A \emph{complex generalized spin-c Killing spinor} on $(M,g)$ with \emph{complex Killing function} $i\mu-\alpha$, where $\alpha$, $\mu\in C^\infty(M,\mathbb{R})$, is a  non-trivial section $\eta\in\Gamma(S)$ of a bundle of irreducible complex spinors $S$ on $(M,g)$ satisfying the following equation:
\begin{equation*}
\nabla^{g,A}_X\eta=\frac{i\alpha+\mu}{2}X\cdot\eta,\qquad X\in\Gamma(TM)
\end{equation*}

for a connection $A\in\Omega^1(P,i\mathbb{R})$ on the characteristic $\mathrm{U}(1)$-bundle $P$ of the spin-c structure $Q$.

\label{rmk:convenciones}
A negative Clifford product convention, denoted in this remark by \emph{bullet} $\bullet$, is defined by setting $X\bullet = -iX\cdot$. Consequently, under this identification, the spinor bundle and the spinorial covariant derivative are unchanged and the Killing equation in Definition~\ref{def:complex-Kill-eq} is given by:
\begin{equation*}
\nabla^{g,A}_X\eta=\frac{i\alpha+\mu}{2}X\cdot\eta=\frac{i\mu-\alpha}{2}X\bullet\eta,\qquad X\in\Gamma(TM).
\end{equation*}

In Appendix~\ref{Ap:Lemma3.4}, we will follow the conventions and notation of~\cite{Grosse_Nakad_2015}. In particular, we will use the negative Clifford multiplication, which will be denoted by $\cdot$ instead of $\bullet$. Furthermore,  the complex Killing function is denoted by $K$, and it is related to our definitions by $K = \frac{i\mu-\alpha}{2}$.

\label{prop:algebraicsquare}
Let $(M,g)$ be an oriented Riemannian surface and let $\mathcal L$ be a Hermitian complex line bundle on $M$. An $\mathcal L$-valued complex exterior form $\rho \in \Omega_\mathbb{C}(M,\mathcal{L})$ is the complex-bilinear square of a nowhere vanishing irreducible complex spinor for some bundle of irreducible complex spinors on $(M,g)$ if and only if:
\begin{equation}
\label{eq:surfacealgebraic}
\rho = c+\theta,\qquad \langle\theta,\theta\rangle=c\otimes c,
\end{equation}
where $c\in\Gamma(\mathcal L)$ and $\theta\in\Omega^1_{\mathbb C}(M,\mathcal L)$ is nowhere vanishing.

Choose a symmetric admissible complex-bilinear pairing of positive adjoint type. Pointwise, $\rho \in \Omega_\mathbb{C}(M,\mathcal{L})$ is the square of a nowhere vanishing irreducible complex spinor if and only if the algebraic conditions in \cite[Thm.~2.7]{Complex_Differential_Spinors_2026} hold. Adapted to the present situation, they reduce to:
\begin{equation*}
\rho \diamond \rho = 2\rho^{(0)}\rho,\qquad \rho\diamond\beta\diamond\rho = 2(\rho \diamond \beta)^{(0)}\rho, \qquad \tau(\rho) = \rho   
\end{equation*}

for a complex exterior form $\beta$ such that $(\rho\diamond\beta)^{(0)} \neq 0$. The linear equation eliminates the degree-two component, so we can write $\rho = c + \theta$ for a section $c\in \Gamma(\mathcal{L})$ and an $\mathcal{L}$-valued one-form $\theta\in\Omega^1_{\mathbb C}(M,\mathcal L)$. The first equation then becomes $\langle\theta,\theta\rangle=c\otimes c$. Since the spinor is nowhere vanishing by assumption, we have $\theta\neq 0$. To apply \cite[Thm.~2.7]{Complex_Differential_Spinors_2026}, we take $\beta=\overline{\theta}$. Then:
\begin{equation*}
(\rho\diamond\overline{\theta})^{(0)}=|\theta|^2>0.
\end{equation*}

With this choice of $\beta$, the second equation above follows automatically from the first. Globalizing this result by properly taking into account that $c$ is a section of $\mathcal{L}$ and $\theta$ is an $\mathcal{L}$-valued one-form, we obtain the statement in the proposition.

\label{prop:complex_Killing_2d}
An oriented Riemannian surface $(M,g)$ admits a generalized Killing spinor with complex Killing function $i\mu-\alpha$ if and only if there exist a Hermitian line bundle $\mathcal L$, a unitary connection $A$ on $\mathcal{L}$, a section $c\in\Gamma(\mathcal{L})$, and a nowhere vanishing $\mathcal{L}$-valued complex one-form $\theta$ satisfying:
\begin{equation}
\label{eq:surfacecovariant}
\nabla^A_Xc=(\mu+i\alpha)\theta(X),\qquad
\nabla^{g,A}_X\theta=(\mu+i\alpha)X^\flat\otimes c,\qquad
\langle\theta,\theta\rangle=c\otimes c
\end{equation}
for every real vector field $X\in\Gamma(TM)$.

By \cite[Lemma~5.3 and Cor.~5.7]{Complex_Differential_Spinors_2026}, a non-zero irreducible complex spinor $\eta$ on $(M,g)$ is Killing with complex Killing function $i\mu -\alpha$ if and only if its square $\rho = c + \theta$ satisfies:
\begin{equation*}
\nabla^{g,A}_X \rho = \frac{\mu+i\alpha}{2} (X^\flat\diamond\rho + \rho \diamond X^\flat).
\end{equation*}

By Proposition~\ref{prop:algebraicsquare}, we can write $\rho = c + \theta$ and, separating by degree, we obtain all equations in~\eqref{eq:surfacecovariant}.

\label{lemma:surfacerealalgebra}
Let $(N,s,v)$ be the real triple associated with a nowhere vanishing irreducible complex spinor on $(M,g)$. Then, for every $X,Y\in\Gamma(TM)$, we have:
\begin{gather}
16|v|^2 =N^2-s^2,\qquad 4|v|^2 = |c|^2 ,\qquad (\theta,c)_{\mathcal{L}} = N v + i s\ast v , \qquad 4|\theta|^2 = N^2+s^2,
\label{eq:surfacerealalgebra}\\
\mathrm{Re}(\theta(Y),\theta(X))_{\mathcal{L}} = \frac{s^2}{4}g(X,Y)+4v(X)v(Y),\qquad
\mathrm{Im}(\theta(Y),\theta(X))_{\mathcal{L}} =\frac{Ns}{4} \mathrm{vol}_g(X,Y).
\label{eq:surfacehermitiantensor}
\end{gather}

Choose a real, positively oriented orthonormal coframe $\{e^1, e^2\}$ and a local unit section $\mathfrak l$ of $\mathcal{L}$. We write:
\begin{equation*}
c=k\mathfrak l,\qquad \theta=(\theta_1e^1+\theta_2e^2)\otimes\mathfrak l
\end{equation*}

for local functions $k$, $\theta_1$, and $\theta_2$. The algebraic relation $\langle \theta , \theta \rangle = c\otimes c$ reduces to $\theta_1^2+\theta_2^2=k^2$. A direct computation gives:
\begin{align*}
(i*(\theta\wedge\overline{\theta}))^2  &=(|\theta_1|^2+|\theta_2|^2)^2 - |\theta_1^2+\theta_2^2|^2 = |\theta|^4-|c|^4,\\
\vert \mathrm{Re}(\theta , c)_{\mathcal{L}}\vert^2 &=\sum_{j=1}^2\mathrm{Re}(\overline{k} \theta_j)^2 =\frac{|c|^2(|c|^2+|\theta|^2)}2.
\end{align*}

On the other hand:
\begin{equation*}
\langle(\theta,c)_{\mathcal{L}},(\theta,c)_{\mathcal{L}} \rangle = |c|^4
\end{equation*}

as well as:
\begin{equation*}
\vert \mathrm{Re}(\theta,c)_{\mathcal{L}}\vert^2 = \frac{N^2|c|^2}{4}, \qquad  \ast (\mathrm{Re}(\theta,c)_{\mathcal{L}} \wedge\mathrm{Im}(\theta,c)_{\mathcal{L}}) =\frac{|c|^2}{2}\,i*(\theta\wedge\overline{\theta}) =\frac{Ns|c|^2}{4}.
\end{equation*}

The preceding two identities give:
\begin{equation*}
\mathrm{Im}(\theta,c)_{\mathcal{L}}
 =\frac{s}{N}*\mathrm{Re}(\theta,c)_{\mathcal{L}}=s*v.
\end{equation*}
Combining these identities together with $\mathrm{Re}(\theta,c)_{\mathcal{L}}=Nv$ gives all equations in~\eqref{eq:surfacerealalgebra}.\medskip

Suppose $c\neq0$ locally. We have:
\begin{equation*}
\theta=\frac{(\theta,c)_{\mathcal{L}}}{|c|^2}\otimes c =\frac{Nv+i s*v}{|c|^2}\otimes c.    
\end{equation*}

Consequently, for every $X,Y\in\Gamma(TM)$ we obtain:
\begin{align*}
4 |c|^2 \mathrm{Re}(\theta(Y),\theta(X))_{\mathcal{L}} &= 4 (N^2v(X)v(Y)+s^2(*v)(X)(*v)(Y))\\
&= s^2 |c|^2 g(X,Y) + 16 |c|^2 v(X)v(Y),\\
4 |c|^2 \mathrm{Im}(\theta(Y),\theta(X))_{\mathcal{L}} &= 4Ns (v\wedge*v)(X,Y) = N|c|^2 s \,\mathrm{vol}_g(X,Y),
\end{align*}

where we are using that $v\otimes v+(*v)\otimes(*v)=|v|^2g$. Using $4|c|^2=N^2-s^2$ gives~\eqref{eq:surfacehermitiantensor} on the locus where $c\neq 0$. To recover the same identities at $c=0$, condition $\langle \theta , \theta \rangle = c\otimes c$ and the assumption $\theta\neq 0$ give $\theta_2=\pm i\theta_1$ with $\theta_1\neq0$. Hence:
\begin{equation*}
N=2|\theta_1|,\qquad s=\pm N,\qquad v=0,    
\end{equation*}

with matching signs, and direct evaluation gives:
\begin{equation*}
\mathrm{Re}(\theta(Y),\theta(X))_{\mathcal{L}}=|\theta_1|^2g(X,Y),\qquad \mathrm{Im}(\theta(Y),\theta(X))_{\mathcal{L}}  =\pm|\theta_1|^2\mathrm{vol}_g (X,Y).
\end{equation*}

These are precisely~\eqref{eq:surfacehermitiantensor}.

The metric compatibility of $\nabla^{g,A}$ and the tensor-product definition of $(-,-)_{\mathcal{L},g}$ give, for every real vector field $X$, the following equations:
\begin{align*}
X(|c|^2) &= 2\mathrm{Re} ((\mu+i\alpha)(\theta(X),c)_{\mathcal{L}}),\\
X(|\theta|^2) &=2\mathrm{Re} ((\mu+i\alpha)(X^\flat\otimes c,\theta)_{\mathcal{L},g}) = 2\mathrm{Re}((\mu-i\alpha)(\theta(X),c)_{\mathcal{L}}).
\end{align*}

In the last equality, we use $(X^\flat\otimes c,\theta)_{\mathcal{L},g}=\overline{(\theta(X),c)}_{\mathcal{L}}$, obtained by evaluating the induced Hermitian metric in a real orthonormal frame. Hence:
\begin{equation*} 
X\bigl(|c|^2+|\theta|^2\bigr)  =4 \mu\,\mathrm{Re}(\theta(X) , c)_{\mathcal{L}}.
\end{equation*}

Since $N^2=2(|\theta|^2+|c|^2)$ in~\eqref{eq:surfacerealalgebra}, it follows that $N\mathrm{d} N=4\mu\,\mathrm{Re}(\theta,c)_{\mathcal{L}}$ and hence $\mathrm{d} N=4\mu v$.\medskip 

The tensor-product rule, using the conjugate connection on $\overline{\mathcal{L}}$ and the parallel Hermitian contraction, gives:
\begin{align*}
X(Ns) &=2i\ast ((\mu+i\alpha)X^\flat\wedge\overline{(\theta,c)}_{\mathcal{L}}-(\mu-i\alpha)X^\flat\wedge(\theta,c)_{\mathcal{L}})\\
&=4\mu s\,v(X)+4\alpha N\,(*v)(X).
\end{align*}

Here we have used~\eqref{eq:surfacerealalgebra} and the identities
$*(X^\flat\wedge v)=-(*v)(X)$ and $*(X^\flat\wedge*v)=v(X)$. Subtracting $s\mathrm{d} N$ and dividing by the positive function $N$ proves $\mathrm{d} s=4\alpha*v$. Furthermore, since $4|c|^2 = N^2 - s^2$ in~\eqref{eq:surfacerealalgebra}, we have the last identity in~\eqref{eq:surfacerealsystem}.\medskip 

For the covariant derivative equations, for every $X,Y\in\Gamma(TM)$, we compute:
\begin{align*}
(\nabla^g_X(\theta,c)_{\mathcal{L}})(Y)&=((\nabla^{g,A}_X\theta)(Y),c)_{\mathcal{L}}+(\theta(Y),\nabla^A_Xc)_{\mathcal{L}}\\
&= (\mu+i\alpha)|c|^2g(X,Y)+(\mu-i\alpha)(\theta(Y),\theta(X))_{\mathcal{L}}.
\end{align*}

Taking real parts and using the pointwise identities~\eqref{eq:surfacehermitiantensor} yields:
\begin{equation*}
\nabla^g\mathrm{Re}(\theta,c)_{\mathcal{L}}=\frac{\mu N^2}{4}g+4\mu v\otimes v+\frac{\alpha Ns}{4}\mathrm{vol}_g .
\end{equation*}

Differentiating the identity $Nv=\mathrm{Re}(\theta,c)_{\mathcal{L}}$ that was obtained in Lemma~\ref{lemma:surfacerealalgebra}, and using $\mathrm{d} N=4\mu v$ it follows that the $v\otimes v$ terms cancel, proving the first identity in~\eqref{eq:nabla-v}. Since the Hodge star operator is parallel and squares to minus the identity on one-forms, we obtain the second identity in~\eqref{eq:nabla-v}. Then we use $\mathscr{L}_X g = 2\mathrm{Sym}(\nabla^g X^\flat)$ and $\mathrm{d} X^\flat = 2\mathrm{Skew}(\nabla^g X^\flat)$ to conclude~\eqref{eq:Lie-dd-v}. The last two identities in~\eqref{eq:surfaceconformalfields} follow, respectively, from evaluating $\mathrm{d} N=4\mu v$ and $\mathrm{d} s=4\alpha*v$ on $(\ast v)^{\sharp}$ and $v^\sharp$ and using $\langle v,*v\rangle=0$. Finally, we use that $\nabla^g$ is torsion-free and~\eqref{eq:nabla-v} to prove the first equation of~\eqref{eq:surfaceconformalfields}.

If $v$ vanished identically, then~\eqref{eq:surfacerealalgebra} would give $s^2=N^2>0$, and the symmetric and skew-symmetric parts of the first equation in~\eqref{eq:nabla-v} would force $\mu=\alpha=0$ everywhere, a contradiction. Thus $v^\sharp$, and consequently $(\ast v)^{\sharp}$, are non-trivial conformal Killing vector fields on $(M,g)$. Choosing a local conformal coordinate $z=x+iy$, we write $v^\sharp = v^x\partial_x + v^y \partial_y$. The trace-free part of the conformal Killing equation gives:
\begin{equation*}
\partial_xv^x=\partial_yv^y,\qquad \partial_y v^x=-\partial_x v^y.
\end{equation*}

Hence $v^x+i v^y$ is holomorphic. The identity theorem and connectedness imply that a conformal field vanishing on a nonempty open subset vanishes identically. Therefore the local holomorphic coefficient of $v^\sharp$ is not identically zero on any coordinate disk, and consequently its zeros are isolated. Since $4|v|^2=|c|^2$ by Lemma~\ref{lemma:surfacerealalgebra}, these zeros are precisely those of $c$. Hence, the common zero set of $c$ and $v$ is closed and discrete.

\label{prop:complex_Killing_2d_frame}
Let $(N, s, v)$ be the real triple associated with a generalized Killing spinor on $(M,g)$ with complex-bilinear square $\rho = c + \theta$. Then its canonical coframe $\{e^1,e^2\}$ satisfies the following differential system on $M^{\circ}\subset M$:
\begin{equation}
\label{eq:surfaceframesystem}
\begin{gathered}
\mathrm{d} e^1 = \alpha\sinh(\phi)\,e^1\wedge e^2,\qquad \mathrm{d} e^2 = \mu\cosh(\phi)\,e^1\wedge e^2,\\
\mathrm{d}\phi = -\mu\sinh(\phi)\,e^1+\alpha\cosh(\phi)\,e^2,\qquad \mathrm{d} f = \mu\cosh(\phi)\,e^1-\alpha\sinh(\phi)\,e^2.
\end{gathered}
\end{equation}

Conversely, given a positively oriented orthonormal coframe $\{e^1,e^2\}$ and real functions $\phi,f,\alpha,\mu$, with $i\mu-\alpha \not\equiv 0$, satisfying the differential system~\eqref{eq:surfaceframesystem} on a connected surface $(M,g)$, there exists a generalized Killing spinor whose complex-bilinear square $\rho=c+\theta$ is given by:
\begin{equation*}
c = e^f \mathfrak l,\qquad \theta=e^f(\cosh(\phi)\,e^1+i\sinh(\phi)\,e^2)\otimes\mathfrak l
\end{equation*}

for a unit section $\mathfrak{l}$ of the trivial complex Hermitian line bundle and the unitary connection $A$ defined by:
\begin{equation*}
\nabla^A\mathfrak l =i(\alpha\cosh(\phi)\,e^1+\mu\sinh(\phi)\,e^2)\otimes\mathfrak l.
\end{equation*}

Since $4|c|^2=N^2-s^2$, the differential system~\eqref{eq:surfacerealsystem} implies:
\begin{equation*}
\mathrm{d}(|c|^2)=2\mu N v-2\alpha s*v,
\qquad
\mathrm{d}(\log|c|)=\frac{\mu N v-\alpha s*v}{|c|^2}.
\end{equation*}

In combination with~\eqref{eq:surfacerealsystem} and~\eqref{eq:surfaceadaptedcoframe}, these identities give the two structure equations and the equation for $\mathrm{d} f$. Differentiating $\tanh(\phi)=s/N$ gives the equation for $\mathrm{d}\phi$.\medskip

For the converse, given $\{e^1 , e^2\}$ and real functions $\phi,f,\alpha,\mu$ as specified in the statement, we define:
\begin{equation*}
\varpi:=\alpha\sinh(\phi)\,e^1+\mu\cosh(\phi)\,e^2,
\qquad \beta:=\alpha\cosh(\phi)\,e^1+\mu\sinh(\phi)\,e^2.
\end{equation*}

The first two equations of~\eqref{eq:surfaceframesystem}, together with Cartan's structure equations, give:
\begin{equation*}
\nabla^ge^1=\varpi\otimes e^2,\qquad
\nabla^ge^2=-\varpi\otimes e^1.
\end{equation*}

Now define the unitary connection $A$ by $\nabla^A\mathfrak{l}=i\beta\otimes\mathfrak{l}$. On the one hand, we have:
\begin{equation*}
\nabla^A c =e^f(\mathrm{d} f+i\beta)\otimes\mathfrak l = (\mu+i\alpha)e^f
(\cosh(\phi)\,e^1+i\sinh(\phi)\,e^2)\otimes\mathfrak l = (\mu+i\alpha)\theta.
\end{equation*}

On the other hand, the equations for $\mathrm{d} f,\mathrm{d}\phi$ and the given formulas for $\varpi,\beta$ give the following identities:
\begin{align*}
\cosh(\phi)(\mathrm{d} f+i\beta)+\sinh(\phi)\,\mathrm{d}\phi-i\sinh(\phi)\,\varpi&=(\mu+i\alpha)e^1,\\
i\sinh(\phi)(\mathrm{d} f+i\beta)+i\cosh(\phi)\,\mathrm{d}\phi+\cosh(\phi)\,\varpi&=(\mu+i\alpha)e^2.
\end{align*}

These are the two coefficient one-forms in the tensor-product covariant derivative of:
\begin{equation*}
\theta := e^f(\cosh(\phi)\,e^1+i\sinh(\phi)\,e^2)\otimes\mathfrak{l}.
\end{equation*}

Therefore:
\begin{equation*}
\nabla^{g,A}\theta = e^f(\mu+i\alpha)(e^1\otimes e^1+e^2\otimes e^2) \otimes\mathfrak l =(\mu+i\alpha)g\otimes c.
\end{equation*}

Finally $\langle\theta,\theta\rangle=c\otimes c$ follows from $\cosh^2(\phi)-\sinh^2(\phi)=1$. We then conclude by Proposition~\ref{prop:complex_Killing_2d}.

\label{thm:surfacelocalnormalform}
Let $(N, s, v)$ be a real triple such that $N>|s|$. The following two are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
    \item There is a complex generalized Killing spinor with real triple $(N,s,v)$.
    \item Around each point of $M$, there are local coordinates $(x,y)$ such that:
    \begin{gather}
        \mathrm{d} x =4(N^2-s^2)^{-1}v, \qquad \mathrm{d} y =4(N^2-s^2)^{-1} * v,\label{eq:dx-dy}\\
        \mathrm{d} N\wedge \mathrm{d} x = 0, \qquad \mathrm{d} s \wedge \mathrm{d} y = 0,\label{eq:dN-ds}\\
        g = (N^2-s^2)(\mathrm{d} x\otimes\mathrm{d} x+\mathrm{d} y\otimes\mathrm{d} y).\label{eq:surfacelocalmetric}
    \end{gather}
\end{enumerate}
Furthermore, if the Killing function is $i\mu-\alpha$ and the complex-bilinear square is $\rho=c+\theta$, then, for a unit section $\mathfrak l$ on the complex Hermitian line bundle, we have:
\begin{gather}
    (N^2-s^2) \mu = \partial_x(N),\qquad (N^2-s^2)\alpha = \partial_y(s),\label{eq:derivadas-direccionales}\\
    2\rho = \sqrt{N^2-s^2}\,  (1+N\mathrm{d} x+i s\mathrm{d} y )\otimes\mathfrak l, \label{eq:surfacelocalsquare}\\
    \nabla^A\mathfrak l=i\beta\otimes\mathfrak l,\qquad (N^2-s^2)\beta = N\partial_y(s)\mathrm{d} x+ s\partial_x(N) \mathrm{d} y.\label{eq:surfacelocalconnection}
\end{gather}

The differential systems~\eqref{eq:surfacerealsystem} and~\eqref{eq:Lie-dd-v} give: 
\begin{equation*}
\label{eq:surface_closed_coordinates}
\mathrm{d} \left(\frac{v}{|c|^2}\right) = 0,\qquad
\mathrm{d} \left(\frac{*v}{|c|^2}\right)=0.
\end{equation*}

These closed one-forms are linearly independent at every point of the regular locus $M^{\circ}$. We choose local primitives $x$ and $y$ such that:
\begin{equation}
\label{eq:dx=v/|c|^2}
\mathrm{d} x=\frac{v}{|c|^2},\qquad \mathrm{d} y=\frac{*v}{|c|^2}. 
\end{equation}

The orthonormal coframe~\eqref{eq:surfaceadaptedcoframe} with $v=|c|^2\mathrm{d} x$ then gives: 
\begin{equation*}
g=4|c|^2(\mathrm{d} x\otimes\mathrm{d} x+\mathrm{d} y\otimes\mathrm{d} y).
\end{equation*}

The first two equations of~\eqref{eq:surfacerealsystem} imply $\mathrm{d} N \wedge \mathrm{d} x =0$ and $\mathrm{d} s \wedge \mathrm{d} y =0$ and~\eqref{eq:derivadas-direccionales}. Since $c\neq 0$ on the regular locus $M^\circ$, we choose the local unit section $\mathfrak{l}:=c/|c|$. Then:
\begin{equation*}
c=|c|\mathfrak{l}=\frac{\sqrt{N^2-s^2}}{2}\mathfrak{l}.
\end{equation*}

The identity $(\theta,c)_{\mathcal{L}}=Nv+i s*v$ gives~\eqref{eq:surfacelocalsquare}; the imaginary part of $\nabla^Ac=(\mu+i\alpha)\theta$ in the unit frame $\mathfrak l$ gives~\eqref{eq:surfacelocalconnection}.\medskip

For the converse, take the trivial complex Hermitian line bundle and the connection given in~\eqref{eq:surfacelocalconnection}, and set:
\begin{equation*}
e^1:=\sqrt{N^2-s^2}\,\mathrm{d} x,\quad
e^2:=\sqrt{N^2-s^2}\,\mathrm{d} y,\quad
c:=\frac{\sqrt{N^2-s^2}}2\mathfrak l,\quad
\theta:=\frac12(Ne^1+i s e^2)\otimes\mathfrak l.
\end{equation*}

Then $\langle\theta,\theta\rangle=c\otimes c$. The coframe connection is:
\begin{equation*}
\varpi=\frac{s\partial_y(s)}{N^2-s^2}\mathrm{d} x+\frac{N\partial_x(N)}{N^2-s^2}\mathrm{d} y.
\end{equation*}

The identities $N\beta-s\varpi=\partial_y(s)\mathrm{d} x$ and $N\varpi-s\beta=\partial_x(N)\mathrm{d} y$ imply:
\begin{equation*}
\nabla^{g,A}\theta
 =\frac{\partial_x(N)+i \partial_y(s)}2(\mathrm{d} x\otimes e^1+\mathrm{d} y\otimes e^2)\otimes\mathfrak l
 =(\mu+i\alpha)g\otimes c.
\end{equation*}

as well as:
\begin{align*}
\nabla^Ac&=\frac{\sqrt{N^2-s^2}}2\left(\frac{N\partial_x(N)\mathrm{d} x-s\partial_y(s)\mathrm{d} y}{N^2-s^2}+i\beta\right)\otimes\mathfrak l\\
&=(\mu+i\alpha)\frac{\sqrt{N^2-s^2}}2(N\mathrm{d} x+i s\mathrm{d} y)\otimes\mathfrak l\\
&=(\mu+i\alpha)\theta.
\end{align*}

Hence, all equations in~\eqref{eq:surfacecovariant} are satisfied and thus we conclude.

\label{prop:surface_killing_tensor}
Let $(N, s, v)$ be the real triple associated with a generalized Killing spinor on $(M,g)$. The symmetric tensor:
\begin{equation}\label{eq:surfacekillingtensor}
N^2g-16v\otimes v=s^2g+16(*v)\otimes(*v)
\end{equation}

is a positive semidefinite quadratic Killing tensor with eigenvalues $s^2,N^2$. If $g$ is complete, then:
\begin{equation}\label{eq:surfaceglobalordering}
|s(p)|\leq N(q)\quad\text{for all }p,q\in M;
\qquad \sup_M|s|\leq\inf_M N.
\end{equation}

First, we substitute~\eqref{eq:dx=v/|c|^2} with $|c|^2 = (N^2 - s^2)/ 4$ in~\eqref{eq:surfacelocalmetric} and obtain:
\begin{equation*}
(N^2-s^2)g = 16v\otimes v+16(*v)\otimes(*v)
\end{equation*}

and, consequently,~\eqref{eq:surfacekillingtensor}. Furthermore, we use $v((*v)^\sharp)=0$ and $*v(v^\sharp)=0$ to conclude that $K:=N^2g-16 v\otimes v$ is a quadratic form with eigenvalues $s^2$, $N^2$. Now we prove $K$ is Killing. To do so, we compute the covariant derivative and use $\mathrm{d} N = 4\mu v$ in~\eqref{eq:surfacerealsystem} and $4 \nabla^g v = \mu N g + \alpha s\, \mathrm{vol}_g $ in~\eqref{eq:nabla-v} to obtain:
\begin{align*}
\nabla^gK &= 2N\mathrm{d} N \otimes g - 16 \nabla^g v\otimes v  - 16 v\otimes \nabla^g v\\
&= 8N\mu  (v\otimes g) - 4 \mu N(g\otimes v + v\otimes g) - 4\alpha s\, (\mathrm{vol}_g \otimes v + v \otimes \mathrm{vol}_g).
\end{align*}

We take the symmetric part and obtain that:
\begin{equation*}
\mathrm{Sym} (\nabla^g K) = 8N\mu  \mathrm{Sym}(v\otimes g) - 4 \mu N \big(\mathrm{Sym}(g \otimes v) + \mathrm{Sym}(v \otimes g)\big)  =0,
\end{equation*}

and thus $K$ is Killing.\medskip

Assume now that $g$ is complete. Let $p,q\in M$ be distinct points in $M$. Since $M$ is connected, the Hopf--Rinow theorem provides a minimizing geodesic joining $p$ to $q$. Parameterizing it by arc length, we obtain:
\begin{equation*}
\gamma:[0,\ell]\longrightarrow M,\qquad
\ell:=d_g(p,q)>0,
\end{equation*}

such that:
\begin{equation*}
\gamma(0)=p,\qquad
\gamma(\ell)=q,\qquad
g_{\gamma(t)}(\dot\gamma(t),\dot\gamma(t))=1.
\end{equation*} 

Since $K$ is Killing, we have that $K_{p}(\dot\gamma(0),\dot\gamma(0))= K_{q}(\dot\gamma(\ell),\dot\gamma(\ell))$. Consequently, we have:
\begin{align*}
s(p)^2 &\leq s(p)^2+
16\bigl((*v)_p(\dot\gamma(0))\bigr)^2 \\
&= K_{p}(\dot\gamma(0),\dot\gamma(0))= K_{q}(\dot\gamma(\ell),\dot\gamma(\ell))
\\
&=
N(q)^2-
16\bigl(v_q(\dot\gamma(\ell))\bigr)^2\leq N(q)^2.
\end{align*}  

Since $N(q)>0$, taking nonnegative square roots finally gives $|s(p)|\leq N(q)$. Note that if $p=q$, the same inequality follows directly from $N(p)^2-s(p)^2=16|v_p|^2\geq 0$. We have therefore proved $|s(p)|\leq N(q)$ for every $p,q\in M$ and, consequently, this proves~\eqref{eq:surfaceglobalordering}. Note that neither the supremum nor the infimum needs to be attained.

Let $(N, s, v)$ be the real triple associated with a generalized Killing spinor on $(M,g)$. If $(M,g)$ is complete, then the vector fields:
\begin{equation}\label{eq:surface_complete_fields}
X:=\frac{4v^\sharp}{N}, \, Y:=4(*v)^\sharp \in\Gamma(TM)
\end{equation}

are complete,  commute, both vanish precisely on the zero locus of $c\in \Gamma(\mathcal{L})$, and their flows preserve $M^\circ$.

Since a bounded vector field on a complete Riemannian manifold is complete and $|4v^\sharp/N|\leq1$, we have that $4v^\sharp/N$ is complete. On the other hand, by~\eqref{eq:surfaceconformalfields} we have $(*v)^\sharp(N)=0$. Along each integral curve of the second vector field, the speed is at most $N$, which is constant along the curve, so the flow is complete. By~\eqref{eq:surfaceconformalfields}, we compute:
\begin{equation*}
[4N^{-1}v^\sharp,4(*v)^\sharp] = 16N^{-1}[v^\sharp,(*v)^\sharp] -16(*v)^\sharp(N^{-1})v^\sharp=0.
\end{equation*}

Finally, since $N>0$ and $4|v|^2=|c|^2$, both vector fields vanish precisely on $\{c=0\}$. Their complete flows fix $\{c=0\}$ pointwise and are diffeomorphisms, so they preserve its complement.

On $\widetilde{M^\circ}$, the lifts $\widetilde{X}$, $\widetilde{Y}$ of the two complete commuting fields in~\eqref{eq:surface_complete_fields} are independent. Thus, their flows define an $\mathbb R^2$-action on $ \widetilde{M^\circ}$ whose orbits are two-dimensional. Since every orbit is open, $ \widetilde{M^\circ}$ has a single orbit because it is connected. Therefore, $\widetilde{M^\circ}$ is diffeomorphic to $\mathbb R^2$ and we can choose a coordinate system $(u,y)\in\mathbb R^2$ such that $\partial_u = \widetilde{X}$ and $\partial_y = \widetilde{Y}$ and $\mathrm{d} u = \widetilde{N} |\widetilde{c}|^{-2} \widetilde{v}$ and $\mathrm{d} y =  |\widetilde{c}|^{-2} * \widetilde{v}$.\medskip

By $\mathrm{d} N = 4\mu v$ in~\eqref{eq:surfacerealsystem}, we have $\mathrm{d} N \wedge \mathrm{d} u =0$. Then we can change the coordinates by:
\begin{equation*}
x(u):=\int_{u_0}^u \frac{\mathrm{d}\tau}{\widetilde{N}(\tau)}
\end{equation*}

with $I = x(\mathbb R)$. Therefore, we obtain $\mathrm{d} x = \widetilde{N}^{-1} \mathrm{d} u$ and global coordinates $(x,y)\in I\times \mathbb R$. Furthermore, because $\mathrm{d} x = |\widetilde{c}|^{-2} \widetilde{v}$ and $\mathrm{d} y =  |\widetilde{c}|^{-2} * \widetilde{v}$ , they coincide with the coordinate system in Theorem~\ref{thm:surfacelocalnormalform} and hence satisfy~\eqref{eq:dx-dy}--\eqref{eq:surfacelocalmetric}  for the real triple $(\widetilde{N},\widetilde{s},\widetilde{v})$. Finally, since $\mathrm{d} x$ and $\mathrm{d} y$ are lifts, they are $\Lambda$-invariant. In other words, for every $\gamma\in\Lambda$ we have $\gamma^* \mathrm{d} x -\mathrm{d} x =\mathrm{d} (x \circ \gamma - x) = 0$. Consequently, in these coordinates, $\Lambda$ is identified with a subgroup of $(\mathbb R^2,+)$.

\label{thm:3.13}
Let $(M,g)$ be a complete Riemannian surface and let $(N,s,v)$ be a real triple with $N > |s|$. Then the following two are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
    \item There exists a complex generalized Killing spinor with real triple $(N,s,v)$.
    \item On $\widetilde{M}$, there exist an open interval $I \subset \mathbb R$ and global coordinates $(x,y) \in I \times \mathbb R $ satisfying~\eqref{eq:dx-dy}--\eqref{eq:surfacelocalmetric} for the real triple $(\widetilde{N},\widetilde{s},\widetilde{v})$.
\end{enumerate}

Furthermore, if $I$ is an open interval, $\Lambda$ is a discrete subgroup acting by translations on $I\times \mathbb R$ and $(\widetilde{N},\widetilde{s},\widetilde{v})$ is a $\Lambda$-invariant real triple satisfying~\eqref{eq:dx-dy}--\eqref{eq:surfacelocalmetric} in the coordinates $(x,y)\in I\times \mathbb R$, then the Riemannian surface $((I\times\mathbb{R})/\Lambda,g)$ with:
\begin{equation*}
\pi^*g=(\widetilde{N}^2-\widetilde{s}^2)(\mathrm{d} x\otimes\mathrm{d} x+\mathrm{d} y\otimes\mathrm{d} y),
\end{equation*}

where $\pi$ is the quotient projection, admits a complex generalized Killing spinor.

On a complete Riemannian surface $(M,g)$, there exists a never chiral complex generalized Killing spinor if and only if, on the universal cover $\widetilde{M}$, there exist global coordinates $(x,y)$ and two $\Lambda$-invariant functions $\widetilde{N}= \widetilde{N}(x)$, $\widetilde{s} = \widetilde{s}(y)$ such that:
\begin{equation*}
\widetilde{g} = (\widetilde{N}(x) ^2 - \widetilde{s}(y)^2)(\mathrm{d} x\otimes\mathrm{d} x+\mathrm{d} y\otimes\mathrm{d} y).
\end{equation*}

Set $4\widetilde v:= (\widetilde{N} ^2 - \widetilde{s}^2) \mathrm{d} x$. If we show that $\widetilde v$ is $\Lambda$-invariant, then we apply Theorem~\ref{thm:3.13} and have finished the proof. Let $\gamma\in\Lambda$ be different from the identity. Since $\widetilde g$ is the lift of $g$, $\mathrm{d} \widetilde N \wedge \mathrm{d} x = 0$ and $\mathrm{d} \widetilde s \wedge \mathrm{d} y = 0$, we have that:
\begin{equation*}
\gamma^*\mathrm{d} x = \pm \mathrm{d} x,\qquad \gamma^*\mathrm{d} y = \pm \mathrm{d} y.
\end{equation*}

If $\gamma^*\mathrm{d} x = \mathrm{d} x$ or $\gamma^*\mathrm{d} x = - \mathrm{d} x$, then, using the $\Lambda$-invariance of the Hodge star operator, we have $\gamma^*\mathrm{d} y =  \mathrm{d} y$ or $\gamma^*\mathrm{d} y = -\mathrm{d} y$, respectively. When $\gamma^*\mathrm{d} x = - \mathrm{d} x$, there exist two constants $A$, $B\in\mathbb R$ such that $\gamma(x,y) = (A-x,B-y)$ and hence $\gamma$ has a fixed point. Because $\Lambda$ acts freely, $\gamma$ must be the identity, a contradiction. Hence $\gamma^*\mathrm{d} x = \mathrm{d} x$, for all $\gamma\in\Lambda$ and, consequently, $\widetilde v = $ is $\Lambda$-invariant.

\label{prop:surfacefilledends}
Let $(M,g)$ be a complete Riemannian surface admitting a generalized Killing spinor with $i\mu-\alpha\not\equiv0$ and square $\rho = c + \theta$, where $c$ has at least one zero. Then precisely one of the following holds:
\begin{equation*}
M\cong\mathbb R^2\text{ with one zero of }c;\qquad
M\cong S^2\text{ with two zeros of }c.
\end{equation*}

In particular, $M^{\circ}$ is diffeomorphic to a cylinder. The metric restricted to $M^{\circ}$ is rotationally symmetric, and either $\alpha\equiv0$ or $\mu\equiv0$. On $M^\circ$ there are oriented coordinates:
\begin{equation}
\label{eq:surfacepolarmetric}
g=\mathrm{d} r\otimes\mathrm{d} r+h(r)^2\mathrm{d} t\otimes\mathrm{d} t, \qquad t\in\mathbb R/(2\pi\mathbb Z),
\end{equation}

where $0<r<\infty$ for the plane and $0<r<L$ for the sphere. At a zero of $c$, $h$ extends smoothly as an odd function of the geodesic radius, with derivative one in the direction away from that zero.

\label{thm:main-zeros}
Let $(M,g)$ be a complete Riemannian surface and let $(N,s,v)$ be a real triple with $|v| = 0$ somewhere. Then the following two are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
    \item There exists a non-parallel generalized Killing spinor with real triple $(N,s,v)$.
    \item There exists a constant $a\neq0$ such that on $M^\circ$ there are positively oriented cylindrical coordinates $(r,t)$ as in~\eqref{eq:surfacepolarmetric} such that one of the following two conditions holds:
    \begin{equation}
    \label{eq:surfacepolar}
    \mathrm{d} s=0,\quad s\neq0,\quad 4v= ah\mathrm{d} r \qquad\text{or}\qquad\mathrm{d} N=0,\quad 4v= ah^2\mathrm{d} t.
    \end{equation}
\end{enumerate}

Furthermore, if the Killing function is $i\mu-\alpha$ and the complex-bilinear square is $\rho=c+\theta$, then, for a unit section $\mathfrak l$ on the complex Hermitian line bundle, we have:
\begin{equation}
\label{eq:surfacepolar-connection}
\begin{gathered}
\mu=\frac{a\partial_r(h)}{N},\quad \alpha=0,\\
2 \rho=(ah+N\mathrm{d} r+i s h\mathrm{d} t)\otimes\mathfrak l\\
\nabla^A\mathfrak l=i\beta\otimes\mathfrak l,\quad \beta=\frac{s\partial_r(h)}{N}\mathrm{d} t
\end{gathered}\qquad\text{or}\qquad
\begin{gathered}
\mu=0,\quad \alpha=-\frac{\partial_r(s)}{ah},\\
2\rho=\bigl(ah-i s\mathrm{d} r+Nh\mathrm{d} t\bigr)\otimes\mathfrak l,\\
\nabla^A\mathfrak l=i\beta\otimes\mathfrak l,\qquad
\beta=\frac{N\alpha}{a}\mathrm{d} t.
\end{gathered}
\end{equation}

We first prove (\rm{i}) implies (\rm{ii}). Proposition~\ref{prop:surfacefilledends} gives a regular cylinder with oriented polar metric:
\begin{equation*}
g=\mathrm{d} r\otimes\mathrm{d} r+h^2\mathrm{d} t\otimes\mathrm{d} t,\qquad
\mathrm{vol}_g =h\mathrm{d} r\wedge\mathrm{d} t,\qquad
\ast\mathrm{d} r=h\mathrm{d} t,\qquad \ast(h\mathrm{d} t)=-\mathrm{d} r,
\end{equation*}

and proves that either $\alpha\equiv0$ or $\mu\equiv0$. These alternatives cannot both hold, by the non-parallel hypothesis. The positively oriented orthonormal coframe $e^1=\mathrm{d} r$, $e^2=h\mathrm{d} t$ satisfies:
\begin{equation*}
\nabla^g e^1=\partial_r(h)\mathrm{d} t\otimes e^2,\qquad
\nabla^g e^2=-\partial_r(h)\mathrm{d} t\otimes e^1.
\end{equation*}

In particular:
\begin{equation*}
\nabla^g(h\mathrm{d} r)=\partial_r(h)g,\qquad
\nabla^g(h^2\mathrm{d} t)=\partial_r(h)\mathrm{vol}_g.
\end{equation*}

If $\alpha\equiv0$ or $\mu\equiv0$, the first two equations in~\eqref{eq:surfacerealsystem} give $\mathrm{d} s = 0$ or $\mathrm{d} N =0$, respectively. The effective circle action used in Proposition~\ref{prop:surfacefilledends} is generated by a non-zero constant multiple of $4(\ast v)^\sharp$ or $4 v^\sharp$, respectively. Thus, after choosing its angular parameter of period $2\pi$, there is a constant $a\neq0$ with:
\begin{equation*}
4(\ast v)^\sharp=a\partial_t,\quad 4v=ah\mathrm{d} r \qquad\text{or}\qquad
4v^\sharp = a\partial_t, \quad 4v= ah^2 \mathrm{d} t,
\end{equation*}

respectively, which proves (\rm{i}) implies (\rm{ii}). Moreover, we compute the norm of $v$ and obtain, in both cases:
\begin{equation}
\label{eq:normas-v-polar}
N^2 - s^2 = 16|v|^2 = a^2 h^2.
\end{equation}

Furthermore, since we are working in the regular locus $M^\circ$, by Theorem~\ref{thm:surfacelocalnormalform}, there exist local coordinates $(x,y)$ and a unit section of the complex Hermitian bundle $\mathfrak l_{(x,y)}$ such that~\eqref{eq:derivadas-direccionales}--\eqref{eq:surfacelocalconnection} are satisfied. Thus, we substitute~\eqref{eq:surfacepolar} in~\eqref{eq:dx-dy}, use~\eqref{eq:normas-v-polar} and obtain, respectively:
\begin{equation}
\label{eq:relacion-dx-dy-dr-dt}
\mathrm{d} x = \frac{\mathrm{d} r}{ah}, \quad \mathrm{d} y = \frac{\mathrm{d} t}{a} \qquad\text{or}\qquad
\mathrm{d} x = \frac{\mathrm{d} t}{a}, \quad \mathrm{d} y = \frac{- \mathrm{d} r}{ah}.
\end{equation}

Finally, we set $\mathfrak l:= \mathrm{sign}(a)\mathfrak l_{(x,y)}$, and substitute~\eqref{eq:relacion-dx-dy-dr-dt} in~\eqref{eq:derivadas-direccionales}--\eqref{eq:surfacelocalconnection} to obtain~\eqref{eq:surfacepolar-connection}.\medskip

Now, we prove (\rm{ii}) implies (\rm{i}). Around every point of $M^\circ$ we can construct a local coordinate system $(x,y)$ defined by the corresponding equations in~\eqref{eq:relacion-dx-dy-dr-dt} and, by the definition of a real triple $(N,s,v)$, we have $N^2 - s^2 = 16|v|^2$. Thus, substituting~\eqref{eq:relacion-dx-dy-dr-dt} in~\eqref{eq:surfacepolarmetric} and~\eqref{eq:surfacepolar}, we obtain~\eqref{eq:dx-dy}--\eqref{eq:surfacelocalmetric}. Consequently, by Theorem~\ref{thm:surfacelocalnormalform}, there exists a complex generalized Killing spinor on $M^\circ$ associated with the data in~\eqref{eq:surfacepolar-connection}. Finally, by Proposition~\ref{prop:reconstruccion-zeros}, which is stated and proved below, any solution satisfying~(\rm{ii}) extends smoothly and uniquely to $M$, giving the existence of a generalized Killing spinor satisfying~(\rm{i}).

\label{prop:reconstruccion-zeros}
Let $M^\circ = (0,L)\times\mathbb R/2\pi\mathbb Z$, with $L\in (0,+\infty]$, be a cylinder with metric:
\begin{equation*}
g=\mathrm{d} r\otimes\mathrm{d} r+h(r)^2\mathrm{d} t\otimes\mathrm{d} t,\qquad(r,t)\in M^\circ,
\end{equation*}

and we suppose that $h>0$ on the open radial interval and that at every included endpoint $h$ has a smooth odd extension in the distance from that endpoint, with derivative one in the direction away from it. We consider a complex generalized Killing spinor whose real triple $(N,s,v)$ satisfies, respectively, the first or second equation in~\eqref{eq:surfacepolar} and~\eqref{eq:surfacepolar-connection}. Then, collapsing the circle at $r=0$ and, when $L<\infty$, at $r=L$, we obtain a complete Riemannian surface $(M,g)$ to which the complex Hermitian line bundle, its connection and the complex-bilinear square of the spinor extend smoothly and uniquely. In particular, $(M,g)$ admits a complex generalized Killing spinor.

We now extend all quantities associated with a generalized Killing spinor with non-trivial chiral locus from $M^{\circ}$ to $M$. We give the extension at $r=0$ first. The smooth odd extension of $h$, together with $\partial_r(h)(0)=1$, implies that $h(r)/r$ extends as a smooth function of $r^2$ with value one at zero. In oriented Cartesian coordinates $x=r\cos(t)$, $y=r\sin(t)$, the metric is:
\begin{equation*}
g=\mathrm{d} x\otimes\mathrm{d} x+\mathrm{d} y\otimes\mathrm{d} y+\frac{(h(r)/r)^2-1}{r^2}(x\mathrm{d} y-y\mathrm{d} x)\otimes(x\mathrm{d} y-y\mathrm{d} x).
\end{equation*}

The scalar coefficient on the second line is a smooth function of $r^2$. This shows the metric is smooth at the collapsed circle, with positive-definite value $\mathrm{d} x\otimes\mathrm{d} x+\mathrm{d} y\otimes\mathrm{d} y$ at its center.\medskip

In the imaginary family ($\mathrm{d} s =0$ and $s\neq0$), $N=\sqrt{s^2+a^2h^2}$ is smooth in $r^2$ near the zero, with $N(0)=|s|$, and $\mu=a\partial_r(h)/N$ extends smoothly. In the real family ($\mathrm{d} N =0$), the relation $s^2 = N^2-a^2h^2$ implies that $s$ has a fixed sign near the zero and extends there as that sign times the positive square root, with $s(0)=\pm N$. Thus $s$ is smooth in $r^2$ there. The formula:
\begin{equation*}
\alpha=\frac{a\partial_r(h)}{s}
\end{equation*}

is valid near the zero and proves smoothness of $\alpha$ there; its use is legitimate because $s$ is non-zero on this neighborhood. In either family put $\varepsilon=\operatorname{sign}s(0)\in\{\pm1\}$. The coefficient of $\mathrm{d} t$ in $\beta$ is a smooth function of $r^2$ with value $\varepsilon$ at zero. Therefore its difference from $\varepsilon$ is $r^2$ times a smooth function of $r^2$.\medskip

Glue a trivial Hermitian line over the polar disk to the line over the regular cylinder by the unitary transition:
\begin{equation*} 
\mathfrak l=e^{i\varepsilon t}\mathfrak l_0,\qquad
\nabla^A\mathfrak l_0
=i(\beta-\varepsilon\mathrm{d} t)\otimes\mathfrak l_0.
\end{equation*}

The transition is single-valued because $\varepsilon$ is an integer. The connection in the disk frame $\mathfrak l_0$ is smooth: indeed, $r^2\mathrm{d} t=x\mathrm{d} y-y\mathrm{d} x$ is smooth, and the preceding vanishing of its coefficient removes the apparent angular singularity. Set $z_\varepsilon=x+i\varepsilon y=r e^{i\varepsilon t}$. This is only notation for a smooth Cartesian coordinate, with orientation reversed when $\varepsilon=-1$. In the disk frame the scalar section is:
\begin{equation}
\label{eq:surfacezeroscalar}
c=\frac a2\frac{h(r)}r z_\varepsilon\mathfrak l_0,
\end{equation}

and it is smooth. If $p$ is a zero of $c$, then:
\begin{equation*}
(\nabla^A c)_p=\frac a2(\mathrm{d} x+i\varepsilon\mathrm{d} y)_p\otimes(\mathfrak l_0)_p.
\end{equation*}

Since $c(p)=0$, this derivative is independent of the choice of connection. As a real-linear map $T_pM\to\mathcal{L}_p$ it is an isomorphism, so the zero of $c$ is simple.\medskip

For the one-form component, the identities:
\begin{equation*}
e^{i\varepsilon t}(\mathrm{d} r+i\varepsilon r\mathrm{d} t)=\mathrm{d} z_\varepsilon,\qquad
r^2e^{i\varepsilon t}(\mathrm{d} r-i\varepsilon r\mathrm{d} t)
=z_\varepsilon^2\mathrm{d}\overline{z}_\varepsilon
\end{equation*}

give the following expressions on the punctured disk. In the imaginary family:
\begin{equation*}
\theta=\left(\frac{N+\varepsilon s  h/r}{4}\mathrm{d} z_\varepsilon+\frac{N-\varepsilon s  h/r}{4r^2}z_\varepsilon^2\mathrm{d}\overline{z}_\varepsilon\right)\otimes\mathfrak l_0.
\end{equation*}

Both scalar coefficients extend as smooth functions of $r^2$: the numerator of the second vanishes at $r=0$, since $N(0)=\varepsilon s =| s |$ and $h(r)/r\to1$. Thus, its quotient by $r^2$ is smooth. The value of $\theta$ at the zero is $| s |\mathrm{d} z_\varepsilon\otimes\mathfrak l_0/2$, which is non-zero. In the real family, the corresponding expression is:
\begin{equation*}
\theta=\left(-\frac{i(s+\varepsilon  N  h/r)}4\mathrm{d} z_\varepsilon-\frac{i(s-\varepsilon  N  h/r)}{4r^2}z_\varepsilon^2\mathrm{d}\overline{z}_\varepsilon\right)\otimes\mathfrak l_0.
\end{equation*}

Here $s(0)=\varepsilon  N  $, so the same argument proves smoothness, and the value at zero is:
\begin{equation*}
-i\varepsilon  N  \mathrm{d} z_\varepsilon\otimes\mathfrak l_0/2\neq0.
\end{equation*}

Thus all line-valued tensors extend smoothly, and $\theta$ remains nowhere vanishing. Since both sides of each equation in~\eqref{eq:surfacecovariant} are smooth and agree off the zero, they agree at the zero as well.\medskip

If a second zero is present, use the positively oriented polar coordinates $(L-r,-t)$ near it. Replacing $a$ and $\mathfrak l$ by $-a$ and $-\mathfrak l$ leaves $c+\theta$, the connection, and the coefficient functions unchanged when expressed in the new coordinates. The same construction therefore applies at this zero, with $\varepsilon$ now equal to the sign of its limiting value of $s$. Take the two polar disks disjoint. Their unitary transition maps with the regular cylinder define a global Hermitian line bundle and the global square and connection just constructed.\medskip

For a solution originally given on $M$, the preceding reconstruction agrees with it on $M^\circ$ under the unitary isomorphism determined by $\mathfrak l=2c/(ah)$. This isomorphism also extends over each zero of $c$. To see this without assuming any regularity of the singular cylinder frame, choose a smooth real vector field $X$ non-zero at that zero. The constructed one-form evaluates non-trivially on $X$ there, by the displayed Cartesian formulas. The original one-form does so as well: at $c=0$,~\eqref{eq:surfacehermitiantensor} gives:
\begin{equation*}
|\theta(X)|_{\mathcal{L}}^2=\frac{N^2}{4}g(X,X)>0.
\end{equation*}

After shrinking the disk, these evaluations are nowhere vanishing sections of the two line bundles. The unique complex-linear map sending the constructed evaluation to the original one defines a smooth line-bundle isomorphism on the disk. On the punctured disk it is the already prescribed isomorphism. By continuity, it is unitary at the center, and it identifies $c,\theta$ and their connections there because the corresponding smooth tensors agree on the punctured disk. This also proves uniqueness, and applies to any two smooth extensions of the same regular data.\medskip

The sphere metric is complete by compactness. For the plane, the extended radial function has range $[0,\infty)$, and the polar metric implies that the length of any piecewise smooth curve is at least the absolute variation of its radial coordinate. Consequently, a closed metric ball about the zero is contained in a set $\{r\leq b\}$ for some finite $b$. This set is compact: it is the image of $[0,b]\times S^1$ with the circle at zero collapsed. The closed ball is therefore compact, and the Hopf--Rinow theorem proves completeness. At $r=0$, the non-zero coefficients are respectively:
\begin{equation*}
\mu(0)=\frac{a}{| s |}\neq0,\qquad
\alpha(0)=\frac{a}{s(0)}\neq0.
\end{equation*}

The same conclusion holds at a second zero after the coordinate change above. Thus every polar reconstruction is non-parallel. Proposition~\ref{prop:complex_Killing_2d} then gives the stated spin-c existence interpretation, without prescribing a spin-c lift in advance.

The previous construction in Proposition~\ref{prop:reconstruccion-zeros} determines the topology of $\mathcal{L}$. Give its fibers their complex orientation and $M$ its prescribed orientation. In the oriented Cartesian coordinates used in the proof,~\eqref{eq:surfacezeroscalar} has local complex coefficient $a h(r)e^{i\varepsilon t}/2$. On a sufficiently small positively oriented circle around the zero, its normalization is:
\begin{equation*}
t\mapsto\frac{a}{|a|}e^{i\varepsilon t}.
\end{equation*}

Its winding number is $\varepsilon$. Hence the local index of the section at every zero $p$ is:
\begin{equation*}
\operatorname{ind}_p(c)=\operatorname{sign}s(p).
\end{equation*}

At a second zero, the same calculation uses the oriented coordinates $(L-r,-t)$; replacing $a$ with $-a$ changes only the constant unit factor, not the index. On a sphere, the first Chern number of a complex line bundle is the sum of the indices of the isolated zeros of a section. Since these two zeros are all the zeros of $c$, it follows that:
\begin{equation*}
{\rm deg}\mathcal{L}:=\langle c_1(\mathcal{L}),[M]\rangle
=\operatorname{sign}s(p_0)+\operatorname{sign}s(p_1)
\in\{-2,0,2\}.
\end{equation*}

In the imaginary family the two signs agree, so ${\rm deg}\mathcal{L}=2\operatorname{sign} s $. In the real family, the degree is zero precisely when the values of $s$ at the zeros have opposite signs. In particular, all these degrees are even, as required by $c_1(\mathcal{L})\bmod2=w_2(TM)=0$ for a characteristic line on the sphere. On the plane, every complex line bundle is trivial because the base is contractible. In the regular case, the nowhere vanishing section $c$ trivializes $\mathcal{L}$, so the characteristic-line condition is satisfied there as well. Triviality of the line bundle does not imply flatness of the specified unitary connection.

\label{cor:surface_complete_separation}
For a generalized Killing spinor with $i\mu-\alpha\not\equiv0$ on a complete Riemannian surface, we have:
\begin{equation*}
\alpha\mu\equiv0\quad\Longleftrightarrow\quad
\alpha\equiv0\ \text{or}\ \mu\equiv0.
\end{equation*}

If neither coefficient vanishes identically, then $c$ is nowhere zero, $\mathcal{L}$ is trivial, and both one-variable functions $N,s$ in the regular normal form are non-constant.

The reverse implication is immediate. Suppose that $\alpha\mu\equiv0$. If $c$ has a zero, Proposition~\ref{prop:surfacefilledends} implies that either $\alpha\equiv0$ or $\mu\equiv0$. Assume therefore that $c$ is nowhere vanishing. By Theorem~\ref{thm:surfacelocalnormalform} and Proposition~\ref{prop:surfaceregularorbit}, on the global regular normal form we have:
\begin{equation*}
(N^2-s^2)\mu= \partial_x(N),\qquad (N^2-s^2)\alpha= \partial_y(s).
\end{equation*}

Since $N^2-s^2>0$, the condition $\alpha\mu\equiv0$ gives $\partial_x(N) \partial_y(s) = 0$ for every $x,y$. Hence either $\partial_x(N)\equiv0$ or $\partial_y(s)\equiv0$, and therefore either $\mu\equiv0$ or $\alpha\equiv0$.\medskip

Finally, if neither $\alpha$ nor $\mu$ vanishes identically, the first part shows that $c$ cannot have zeros. Thus $c$ trivializes $\mathcal{L}$, and the equations above imply that both $N$ and $s$ are non-constant.

\label{cor:surfacecompactclassification}
An oriented compact Riemannian surface admits a generalized Killing spinor with $i\mu-\alpha\not\equiv0$ if and only if one of the following holds:
\begin{enumerate}[label=\textup{(\roman*)}]
\item It is a rotationally symmetric sphere. In particular, $\alpha\equiv0$ or $\mu\equiv0$.
\item It is a torus with a global presentation $(M,g)=(\mathbb{R}^2/\Lambda,g)$ with:
\begin{equation*}
\pi^*g=(\widetilde{N}(x)^2-\widetilde{s}(y)^2)(\mathrm{d} x\otimes\mathrm{d} x+\mathrm{d} y\otimes\mathrm{d} y),
\end{equation*}
where $\pi$ is the quotient projection, $\Lambda$ is a full lattice, and $\widetilde{N}$, $\widetilde{s}$ are two $\Lambda$-invariant functions with $\widetilde{N}>|\widetilde{s}|$, and at least one of $\widetilde{N}$, $\widetilde{s}$ is non-constant.
\end{enumerate}

Furthermore, in {\rm(i)}, every such solution has two simple zeros of $c$ and belongs to one of the families in Theorem~\ref{thm:main-zeros}. In {\rm(ii)}, $c$ is nowhere zero and $\mathcal{L}$ is trivial.

For a toroidal solution, $c$ is nowhere zero. Since $4|v|^2=|c|^2$, it follows that $v$ is nowhere vanishing. By compactness, the function $N+s$ attains a maximum at some point $p\in M$. The real differential system gives:
\begin{equation*}
0=\mathrm{d}(N+s)_p=4\mu(p)v_p+4\alpha(p)(*v)_p.
\end{equation*}

Since the one-forms $v_p$ and $(*v)_p$ are non-zero and orthogonal, they are
linearly independent. Hence, $\mu(p)=\alpha(p)=0$.

\label{prop:spin-plano}
Let $M\subset\mathbb{C}$ be a connected open set endowed with the Euclidean metric. Then there exists a complex generalized spin Killing spinor $\eta\in\Gamma(S)$ with complex Killing function $i\mu-\alpha\not\equiv0$ such that $\rho = c + \theta$ is its complex-bilinear square if and only if there exist two functions $F(z):=-az+b_1$ and $G(z):=a\overline z+b_2$ for some constants $a$, $b_1$, $b_2\in\mathbb{C}$ with $a\neq0$ such that:
\begin{equation*} 
\theta=i(F-G)\mathrm{d} x+(F+G)\mathrm{d} y, \qquad c^2=4\,FG, \qquad(i\alpha + \mu) c = -2 i \,a.
\end{equation*}

We can write $\theta = u \mathrm{d} x + v \mathrm{d} y$ and the second equation in~\eqref{eq:spin-Kill}, applied to $X= \frac{\partial}{\partial x}$ and $X= \frac{\partial}{\partial y}$, respectively, becomes:
\begin{equation*}
\frac{\partial u}{\partial x} \mathrm{d} x + \frac{\partial v}{\partial x} \mathrm{d} y = (i\alpha + \mu)c \mathrm{d} x,\qquad \frac{\partial u}{\partial y} \mathrm{d} x + \frac{\partial v}{\partial y} \mathrm{d} y = (i\alpha + \mu)c \mathrm{d} y.
\end{equation*}

In other words, $\mathrm{d} u = (i\alpha + \mu)c \, \mathrm{d} x$, and $\mathrm{d} v = (i\alpha + \mu)c \, \mathrm{d} y$. We define:
\begin{equation*}
F:=\frac{v-iu}{2}, \qquad G:=\frac{v+iu}{2}.
\end{equation*}

Differentiating, we obtain that:
\begin{equation*}
\mathrm{d} F = - \frac{i(i\alpha + \mu)c}{2} \mathrm{d} z, \qquad \mathrm{d} G = \frac{i(i\alpha + \mu)c}{2} \mathrm{d} \overline{z}.
\end{equation*}

Thus, $F$ is holomorphic, $G$ is anti-holomorphic, and:
\begin{equation*}
-\frac{\partial F}{\partial x} = \frac{\partial G}{\partial x} = \frac{i(i\alpha + \mu)c}{2}, \qquad \frac{\partial F}{\partial y} = \frac{\partial G}{\partial y} = \frac{(i\alpha + \mu)c}{2}.
\end{equation*}

Thus, $\frac{i(i\alpha + \mu)c}{2}$ is holomorphic and anti-holomorphic and, consequently, it must be equal to a constant $a\in\mathbb{C}$. Moreover, $a\neq0$. Indeed, if $a=0$, then $(i\alpha+\mu)c=0$. Since $i\alpha+\mu\not\equiv0$, the open set $U:=\{p\in M\mid (i\alpha+\mu)(p)\neq0\}$ is nonempty. On $U$ we have $c=0$, hence $\mathrm{d} c=0$. The first equation in~\eqref{eq:spin-Kill} then gives $0=\mathrm{d} c=(i\alpha+\mu)\theta$ on $U$, contradicting the fact that $\theta$ is nowhere vanishing. Finally, there exist two constants $b_1$ and $b_2\in\mathbb{C}$ such that:
\begin{equation*}
F(z) = -az + b_1, \qquad G(z) = a \overline z + b_2.
\end{equation*}

Moreover:
\begin{equation*}
c^2=\langle\theta,\theta\rangle=- (F-G)^2+(F+G)^2=4FG.
\end{equation*}

Conversely, since $a\neq0$ and $(i\alpha + \mu) c = -2 i \,a$, both $c$ and $i\alpha+\mu$ are nowhere vanishing. We differentiate $c^2 = 4 \,FG$ and obtain:
\begin{align*}
\mathrm{d} c &= \frac{2}{c} ( F \mathrm{d} G +  G \mathrm{d} F) \\
    &= \frac{2}{c} \left(F\frac{i(i\alpha + \mu)c}{2} \mathrm{d} \overline{z} - G \frac{i(i\alpha + \mu)c}{2} \mathrm{d} z  \right)\\
    &= i(i\alpha + \mu) \left(F \mathrm{d} x - F i\mathrm{d} y - G\mathrm{d} x -Gi\mathrm{d} y \right) \\
    &= (i\alpha + \mu) \left(i(F-G) \mathrm{d} x + (F +G) \mathrm{d} y\right) \\
    &= (i\alpha + \mu) \theta,
\end{align*}

which is the first identity in Equation~\eqref{eq:spin-Kill}. Analogously, taking the $\nabla^g$-derivative of $\theta$, we obtain:
\begin{align*}
\nabla^g\theta &= i (\mathrm{d} F - \mathrm{d} G)\otimes \mathrm{d} x + (\mathrm{d} F + \mathrm{d} G)\otimes \mathrm{d} y \\
    &= i \left(- \frac{i(i\alpha + \mu)c}{2}\right) (\mathrm{d} z + \mathrm{d} \overline{z})\otimes \mathrm{d} x + \left(- \frac{i(i\alpha + \mu)c}{2}\right) (\mathrm{d} z - \mathrm{d} \overline{z}) \otimes \mathrm{d} y \\
    &= (i\alpha + \mu)c g,
\end{align*}

which is the second identity in Equation~\eqref{eq:spin-Kill}. Together with $\langle\theta,\theta\rangle=c^2$, Proposition~\ref{prop:complex_Killing_2d} gives the required generalized spin Killing spinor.

\label{ex:spin-counterexample}
Let $M= \{z=x+iy\in \mathbb{C}\mid |z|< \tfrac{1}{2}\}$ and equip $M$ with the Euclidean metric $g$ and the standard spin structure with complex spinor bundle $S$. Let $\sqrt{z}$ be the principal branch of the square root on $\mathbb{C} \setminus\{x\leq0,\,y=0\}$. We define:
\begin{equation*}
F(z) := 1-z, \qquad G(z) :=  \overline z + i,\qquad c := 2\sqrt{1-z}\sqrt{\overline{z}+i}.
\end{equation*}

Therefore, by Proposition~\ref{prop:spin-plano}, there exists a complex generalized spin Killing spinor with complex Killing function:
\begin{equation*}
-\alpha(z) + i\mu(z) = \frac{1}{\sqrt{1-z}\sqrt{\overline{z}+i}}.
\end{equation*}

We now evaluate at $z=0$ and obtain:
\begin{equation*}
-\alpha(0)+i\mu(0)=\frac{1}{\sqrt{i}}=\frac{1-i}{\sqrt{2}}
\end{equation*}

and $\alpha(0)\mu(0)=\frac{1}{2}\neq0$. This example is a proper complex generalized spin Killing spinor with complex Killing function $i\mu-\alpha$ with $\alpha\mu\not\equiv 0$ and, therefore, contradicts~\cite[Lemma~3.4]{Grosse_Nakad_2015} in dimension two.

\label{ex:nowhere-vanishing}
Let us consider the following oriented and connected two-dimensional manifold:
\begin{equation*}
M:=\{(x,y)\in\mathbb{R}^2\mid y<x\}\subset\mathbb{R}^2.
\end{equation*}

Take $t:=e^{y-x}$, so $0<t<1$, and define $\phi:=\operatorname{arctanh}(t)$, so that:
\begin{equation*}
\cosh(\phi)=\frac{1}{\sqrt{1-t^2}},\qquad \sinh(\phi)=\frac{t}{\sqrt{1-t^2}}.
\end{equation*}

Set:
\begin{equation*}
e^1:=\sqrt{1-t^2}\mathrm{d} x,\qquad e^2:=\frac{\sqrt{1-t^2}}{t}\mathrm{d} y
\end{equation*}

and equip $M$ with the Riemannian metric $g:=e^1\otimes e^1+e^2\otimes e^2$. Finally, define:
\begin{equation*}
\alpha:=\frac{t^2}{1-t^2},\qquad \mu:=\frac{1}{1-t^2}.
\end{equation*}

In particular, they satisfy that $\alpha>0$ and $\mu>0$ on $M$. We can explicitly check all the conditions in Proposition~\ref{prop:complex_Killing_2d_frame}. First of all:
\begin{equation*}
\mu\cosh(\phi)e^1-\alpha\sinh(\phi)e^2=\frac{1}{1-t^2}(\mathrm{d} x-t^2\mathrm{d} y)=\mathrm{d}(x+\tfrac{1}{2}\log(1-t^2)),
\end{equation*}

where we have used that $\mathrm{d} t=t(\mathrm{d} y-\mathrm{d} x)$. Hence, the above one-form is exact. Now, using that $e^1\wedge e^2=\frac{1-t^2}{t}\mathrm{d} x\wedge \mathrm{d} y$ we obtain:
\begin{align*}
\mathrm{d} e^1&=\frac{t^2}{\sqrt{1-t^2}}\mathrm{d} x\wedge \mathrm{d} y=\alpha\sinh(\phi)e^1\wedge e^2,\\
\mathrm{d} e^2&=\frac{1}{t\sqrt{1-t^2}}\mathrm{d} x\wedge\mathrm{d} y=\mu\cosh(\phi)e^1\wedge e^2.
\end{align*}

Finally, the function $\phi=\operatorname{arctanh}(t)$ satisfies:
\begin{equation*}
\mathrm{d}\phi=\frac{1}{1-t^2}\mathrm{d} t=\frac{t}{1-t^2}(\mathrm{d} y-\mathrm{d} x)=-\mu\sinh(\phi)e^1+\alpha\cosh(\phi)e^2.
\end{equation*}

Therefore, we have constructed an example of a Riemannian surface carrying a generalized spin-c Killing spinor with complex Killing function $i\mu-\alpha$ for which $\alpha\mu>0$.

\label{ex:alpha.mu=0-2}
Let us consider the following oriented and connected two-dimensional manifold:
\begin{equation*}
M:=\{(x,y)\in\mathbb{R}^2\mid x>0\text{ or }y<0\}\subset\mathbb{R}^2.
\end{equation*}

Choose non-constant smooth functions $F,G\colon\mathbb{R}\to[0,\infty)$ such that $F(x)=0$ for $x\geq0$ and $G(y)=0$ for $y\leq0$. Now fix a positive constant $\phi_0>0$ and define:
\begin{align*}
\phi(x,y)&:=\phi_0+F(x)+G(y)>0,\\
f(x,y)&:=-\log\cosh(\phi_0+F(x))-\log\sinh(\phi_0+G(y)).
\end{align*}

Set:
\begin{equation*}
e^1:=\frac{1}{\cosh(\phi)}\mathrm{d} y,\qquad e^2:=-\frac{1}{\sinh(\phi)}\mathrm{d} x
\end{equation*}

and equip $M$ with the Riemannian metric $g=e^1\otimes e^1+e^2\otimes e^2$. Finally, define:
\begin{equation*}
\alpha:=-F'(x)\tanh(\phi),\qquad \mu:=-\frac{G'(y)}{\tanh(\phi)}.
\end{equation*}

If $F'(x)\neq0$, then $x<0$. But on $M$, $x<0$ implies that $y<0$, thus $G'(y)=0$. Similarly, if $G'(y)\neq0$, then $y>0$, which implies that $x>0$, thus $F'(x)=0$. Therefore $\alpha\mu\equiv0$ everywhere on $M$, while $\alpha\not\equiv0$ and $\mu\not\equiv0$. A direct computation shows that all the equations in Proposition~\ref{prop:complex_Killing_2d_frame} are satisfied. Therefore, we have constructed an example of a Riemannian surface carrying a generalized spin-c Killing spinor with complex Killing function $i\mu-\alpha$ for which $\alpha\mu\equiv0$ but neither $\alpha$ nor $\mu$ is identically zero.

\label{example:complete_2d}
Consider $\mathbb{R}^2$ and choose constants $a,b>0$ and $C>a+b$. Define:
\begin{equation*}
A(y):=a\tanh(y),\qquad B(x):=C+b\tanh(x),\qquad t(x,y):=e^{A(y)-B(x)}
\end{equation*}

and:
\begin{equation*}
f(x,y):=B(x)+\frac{1}{2}\log(1-t(x,y)^2).
\end{equation*}

Since $-a<A(y)<a$ and $C-b<B(x)<C+b$, we have $0<m\leq t(x,y)\leq M<1$ for some constants $m,M$. In particular, the function $\phi:=\operatorname{arctanh}(t)>0$ is globally defined. Set:
\begin{equation*}
e^1:=\sqrt{1-t^2}\mathrm{d} x,\qquad e^2:=\frac{\sqrt{1-t^2}}{t}\mathrm{d} y
\end{equation*}

and equip $\mathbb{R}^2$ with the Riemannian metric $g:=e^1\otimes e^1+e^2\otimes e^2$. Finally, define:
\begin{equation*}
\alpha:=A'(y)\frac{t^2}{1-t^2},\qquad \mu:=B'(x)\frac{1}{1-t^2}.
\end{equation*}

Since $A'(y)=\frac{a}{\cosh^2(y)}>0$ and $B'(x)=\frac{b}{\cosh^2(x)}>0$, we have that $\alpha>0$, $\mu>0$, and $\alpha\mu>0$. A direct computation shows that all the equations in Proposition~\ref{prop:complex_Killing_2d_frame} are satisfied. We now show completeness of the metric $g$. Since:
\begin{equation*}
g=e^1\otimes e^1+e^2\otimes e^2=(1-t^2)\mathrm{d} x\otimes\mathrm{d} x+\frac{1-t^2}{t^2}\mathrm{d} y\otimes\mathrm{d} y
\end{equation*}

and $0<m\leq t\leq M<1$ we have:
\begin{equation*}
0<1-M^2\leq1-t^2\leq1-m^2<1,\qquad 0<\frac{1-M^2}{M^2}\leq\frac{1-t^2}{t^2}\leq\frac{1-m^2}{m^2}<\infty.
\end{equation*}

From these inequalities we conclude that there exists a real constant $K\geq1$ such that:
\begin{equation*}
\frac{1}{K}g_0\leq g\leq Kg_0,
\end{equation*}

where $g_0:=\mathrm{d} x\otimes\mathrm{d} x+\mathrm{d} y\otimes\mathrm{d} y$ is the Euclidean metric on $\mathbb{R}^2$. Hence, the metric $g$ is uniformly equivalent to the Euclidean metric $g_0$, which is complete. Therefore, the metric $g$ is also complete.

\label{ex:compact}
Let us consider the same data as in Example~\ref{example:complete_2d} but taking instead:
\begin{equation*}
A(y):=a\sin(y),\qquad B(x):=C+b\sin(x),
\end{equation*}

which are $2\pi$-periodic functions. Then the whole construction descends to the torus $T^2=\mathbb{R}^2/(2\pi\mathbb{Z})^2$, giving us an example of a compact Riemannian surface carrying a generalized spin-c Killing spinor with complex Killing function $i\mu-\alpha$ such that:
\begin{equation*}
\alpha\mu=ab\cos(x)\cos(y)\frac{t^2}{(1-t^2)^2}.
\end{equation*}

Note that this expression is non-zero on an open dense set and takes both signs. At points where $\cos(x)=\cos(y)=0$, both coefficients vanish, in agreement with Corollary~\ref{cor:surfacetorusconsequences}.

\label{prop:complex_Killing}
A three-dimensional spin-c Riemannian manifold $(M,g)$ admits a complex generalized spin-c Killing spinor $\eta\in\Gamma(S)$ with complex Killing function $i\mu-\alpha$, where $\alpha$, $\mu\in C^\infty(M,\mathbb{R})$, if and only if:
\begin{equation*}
\nabla^{g,A}_X\rho=(i\mu-\alpha)*(X^\flat\wedge\rho)
\end{equation*}

for all $X\in\Gamma(TM)$, where $\rho$ denotes the complex-bilinear square of $\eta$.

Recall that we have equipped the bundle of irreducible complex spinors $S$ with a skew-symmetric admissible bilinear pairing $\Scr B$ of negative adjoint type. As explained in~\cite{LBC13,LBC16}, and further elaborated in~\cite{Algebraic_Complex_Square_2025}, the truncated Kähler-Atiyah bundle is defined on $\wedge^<T^*_\mathbb{C} M=\mathbb{C}\oplus T^*_\mathbb{C} M$ endowed with the product:
\begin{equation*}
\rho_1\vee\rho_2=\mathcal{P}_<(\rho_1\diamond\rho_2-i*\tau(\rho_1\diamond\rho_2))
\end{equation*}

for all $\rho_1$, $\rho_2\in\wedge^<T^*_\mathbb{C} M$. Here $\mathcal{P}_<\colon\wedge T^*_\mathbb{C} M\to\wedge^<T^*_\mathbb{C} M$ is the natural projection, $\diamond$ denotes the geometric product, and $\tau$ is the reversion anti-automorphism that acts as multiplication by $\smash{(-1)^{\binom{k}{2}}}$ on $k$-forms. By~\cite[Thm.\ 5.10]{Complex_Differential_Spinors_2026}, the equation $\nabla^{g,A}_X\eta=\frac{i\alpha+\mu}{2}X\cdot\eta$ is equivalent to:
\begin{equation*}
\nabla^{g,A}_X\rho=\frac{i\alpha+\mu}{2}(X^\flat\vee\rho-\rho\vee X^\flat)=\frac{i\alpha+\mu}{2}(2i*(X^\flat\wedge\rho))=(i\mu-\alpha)*(X^\flat\wedge\rho),
\end{equation*}

which proves the statement.

\label{lemma:nabla_zeta}
The one-form $\zeta\in\Omega^1(M)$ constructed above from the complex-bilinear square $\rho$ satisfies:
\begin{equation*}
\nabla^g_X\zeta=-\alpha\iota_X\omega+\mu(X^\flat-\zeta(X)\zeta)
\end{equation*}

for all $X\in\Gamma(TM)$. Moreover, $\mathrm{d}(\log\langle\rho,\overline{\rho}\rangle)=2\mu\zeta$.

Let $c:=i\mu-\alpha\in C^\infty(M,\mathbb{C})$. Then $\nabla^{g,A}_X\rho=c*(X^\flat\wedge\rho)$ for all $X\in\Gamma(TM)$ by Proposition~\ref{prop:complex_Killing}. We first compute the derivative of $u:=\langle\rho,\overline{\rho}\rangle$. Using $\langle\rho,*(X^\flat\wedge\overline{\rho})\rangle=-\langle*(X^\flat\wedge\rho),\overline{\rho}\rangle$ and $c-\overline{c}=2i\mu$ we obtain:
\begin{equation*}
X(u)=2i\mu\langle*(X^\flat\wedge\rho),\overline{\rho}\rangle.
\end{equation*}

Using $\rho\wedge\overline{\rho}=-iu*\zeta$ we obtain:
\begin{equation*}
\langle*(X^\flat\wedge\rho),\overline{\rho}\rangle\mathrm{vol}_g =X^\flat\wedge\rho\wedge\overline{\rho}=-iuX^\flat\wedge*\zeta=-iu\zeta(X)\mathrm{vol}_g ,
\end{equation*}

where $\mathrm{vol}_g $ is the Riemannian volume form. Hence $X(u)=2u\mu\zeta(X)$ for all $X\in\Gamma(TM)$, which is equivalent to $\mathrm{d}(\log u)=2\mu\zeta$.\medskip

Now define the $(0,2)$-tensor field $T$ by $T(X,Y):=\iota_Y(*(*(X^\flat\wedge\rho)\wedge\overline{\rho}))$ for all $X$, $Y\in\Gamma(TM)$. Then:
\begin{align*}
T(X,Y)&=\iota_Y(*(*(X^\flat\wedge\rho)\wedge\overline{\rho}))=*(*(X^\flat\wedge\rho)\wedge\overline{\rho}\wedge Y^\flat)\\
&=-*(Y^\flat\wedge\overline{\rho}\wedge*(X^\flat\wedge\rho))=-*\langleY^\flat\wedge\overline{\rho},X^\flat\wedge\rho\rangle\mathrm{vol}_g \\
&=-\langleX^\flat\wedge\rho,Y^\flat\wedge\overline{\rho}\rangle=\overline{\rho}(X)\rho(Y)-ug(X,Y).
\end{align*}

Using the above relation and:
\begin{align*}
\overline{\rho}(X)\rho(Y)+\rho(X)\overline{\rho}(Y)&=u(g(X,Y)-\zeta(X)\zeta(Y)),\\
\overline{\rho}(X)\rho(Y)-\rho(X)\overline{\rho}(Y)&=(\overline{\rho}\wedge\rho)(X,Y)=iu(*\zeta)(X,Y)
\end{align*}

we obtain:
\begin{align*}
(\nabla^g_X\zeta)Y&=-2\mu\zeta(X)\zeta(Y)+\frac{ic}{u}T(X,Y)-\frac{i\overline{c}}{u}\overline{T(X,Y)}\\
&=\alpha(*\zeta)(X,Y)+\mu(g(X,Y)-\zeta(X)\zeta(Y)).
\end{align*}

Therefore, using $\omega=-*\zeta$, we have $\nabla^g_X\zeta=-\alpha\iota_X\omega+\mu(X^\flat-\zeta(X)\zeta)$ for all $X\in\Gamma(TM)$.

\label{lemma:nabla_omega}
The two-form $\omega\in\Omega^2(M)$ satisfies:
\begin{equation*}
\nabla^g_X\omega=\alpha X^\flat\wedge\zeta+\mu\iota_X\omega\wedge\zeta
\end{equation*}

for all $X\in\Gamma(TM)$.

Decompose the vector field $X$ as $X=X_\mathcal{D}+\zeta(X)\xi$, where $X_\mathcal{D}\in\Gamma(\mathcal{D})$. Then $X^\flat=X_\mathcal{D}^\flat+\zeta(X)\zeta$. Applying the Hodge star operator, we get:
\begin{equation*}
*(X^\flat\wedge\rho)=*(X_\mathcal{D}^\flat\wedge\rho)+\zeta(X)*(\zeta\wedge\rho).
\end{equation*}

Using $*e^1=-e^2\wedge\zeta$ and $*e^2=e^1\wedge\zeta$ we see that $*\rho=i\zeta\wedge\rho$. Hence $*(\zeta\wedge\rho)=-i\rho$. Multiplying by $(i\mu-\alpha)\zeta(X)$ we obtain:
\begin{equation*}
(i\mu-\alpha)\zeta(X)*(\zeta\wedge\rho)=(\mu+i\alpha)\zeta(X)\rho.
\end{equation*}

For the other term, we obtain:
\begin{equation*}
*(X_\mathcal{D}^\flat\wedge\rho)=-\iota_{X_\mathcal{D}}(*\rho)=i\rho(X_\mathcal{D})\zeta=i\rho(X)\zeta
\end{equation*}

since $X_\mathcal{D}\in\Gamma(\mathcal{D})$ and $\rho(\xi)=0$. Multiplying by $i\mu-\alpha$ we obtain:
\begin{equation*}
(i\mu-\alpha)*(X_\mathcal{D}^\flat\wedge\rho)=-(\mu+i\alpha)\rho(X)\zeta.
\end{equation*}

Combining both terms, we precisely obtain:
\begin{equation*}
(i\mu-\alpha)*(X^\flat\wedge\rho)=(\mu+i\alpha)(\zeta(X)\rho-\rho(X)\zeta),
\end{equation*}

which matches the expression for $\nabla^{g,A}_X\rho$ in Equation~\eqref{eq:nabla_rho}, thereby concluding the proof.

Since $(g,\varphi,\xi,\zeta)$ is trans-Sasakian, it satisfies the following equations:
\begin{equation*}
\mathrm{d}\zeta=-2\alpha\omega, \qquad \mathrm{d}\omega=2\mu\zeta\wedge\omega.
\end{equation*}

By assumption, $\mu\zeta$ is closed. Hence:
\begin{equation*}
0 =\mathrm{d}(\mu\zeta)  =\mathrm{d}\mu\wedge\zeta+\mu\mathrm{d}\zeta = \mathrm{d}\mu\wedge\zeta-2\alpha\mu\omega.
\end{equation*}

Taking the exterior product with $\zeta$, and using that $\zeta\wedge\omega$ is nowhere vanishing, we obtain $\alpha\mu\equiv0$, and therefore we conclude that $\mathrm{d}\mu\wedge\zeta=0$. Evaluating at $\xi$, we obtain:
\begin{equation}
\label{eq:dmuReeb}
\mathrm{d}\mu=\xi(\mu)\zeta,
\end{equation}

and consequently:
\begin{equation*}
\label{eq:horizontal-mu}
X(\mu)=0
\end{equation*}

for every $X\in\Gamma(\mathcal{D})$, where $\mathcal{D}:=\mathrm{Ker}(\zeta)$. On the other hand:
\begin{equation*}
0=\mathrm{d}^2\zeta = -2\mathrm{d}\alpha\wedge\omega-2\alpha\mathrm{d}\omega = - 2 (\xi(\alpha)+2\alpha\mu ) \zeta\wedge\omega,
\end{equation*}

where we have used that $\mathrm{d}\alpha\wedge\omega = \xi(\alpha)\zeta\wedge\omega$. Consequently:
\begin{equation*}
\xi(\alpha)+2\alpha\mu\equiv0.
\end{equation*}

Since $\alpha\mu\equiv0$, this equation reduces to $\xi(\alpha)=0$. Since we are assuming that $\xi$ is complete, it generates a globally defined flow:
\begin{equation*}
\Phi\colon\mathbb{R}\times M\longrightarrow M, \qquad (t,p)\longmapsto\Phi_t(p).   
\end{equation*}

Furthermore, we have:
\begin{equation*}
\mathscr{L}_\xi\zeta = \mathrm{d} (\zeta(\xi))+\iota_\xi\mathrm{d}\zeta = \iota_\xi(-2\alpha\omega) = 0,
\end{equation*}

and therefore the flow of the characteristic vector field $\xi$ preserves both $\zeta$ and its kernel:
\begin{equation*}
\label{eq:Reeb-preserves-D}
\Phi_t^*\zeta=\zeta, \qquad (\Phi_t)_*\mathcal{D}=\mathcal{D}
\end{equation*}

for every $t\in\mathbb{R}$. Suppose that $\alpha$ is not everywhere vanishing, and choose a point $p\in M$ such that $\alpha(p)\neq 0$. Let $U$ be the connected component of the open set $\{\alpha\neq0\}$ containing $p$. Restricting to $U$, we have:
\begin{equation*}
(\zeta\wedge\mathrm{d}\zeta) \vert_U = -2\alpha\,\zeta\wedge\omega\neq 0.    
\end{equation*} 

Hence, the restriction $\mathcal{D}|_U$ of $\mathcal{D}$ to $U$ is a contact distribution and, in particular, its sheaf of local sections together with their Lie brackets generate the sheaf of local sections of $TU$, that is:
\begin{equation*}
\mathcal{D}|_U+[\mathcal{D}|_U,\mathcal{D}|_U]=TU.
\end{equation*}

By a classical result of Chow and Rashevskii, it then follows that any two points of $U$ can be joined by a piecewise smooth curve whose tangent vector belongs to $\mathcal{D}$.\medskip

Let $\mathcal{P}_{\mathcal{D}}$ denote the pseudogroup generated by the local flows of local sections of $\mathcal{D} \subset TM$. By definition, an element $\Psi\in\mathcal{P}_{\mathcal{D}}$ is a finite composition of local flows of such vector fields, that is:
\begin{equation*}
\Psi = \Phi^{X_k}_{t_k}\circ\cdots\circ\Phi^{X_1}_{t_1},
\end{equation*}

where each $X_j$ is a local section of $\mathcal{D}$ and each $\Phi^{X_j}_{t_j}$ is a local flow map. Every such element $\Psi \in \mathcal{P}_{\mathcal{D}}$ is a diffeomorphism between open subsets of $M$, since each local flow map is a diffeomorphism onto its image. We define the orbit of $p$ with respect to $\mathcal{P}_{\mathcal{D}}$ by:
\begin{equation*}
\mathcal{O}_{\mathcal{D}}(p) := \left\{ \Psi(p)\mid\Psi\in\mathcal{P}_{\mathcal{D}} \right\}.
\end{equation*}

Implicit in the previous definition of the orbit is the fact that we only consider the elements $\Psi\in \mathcal{P}_{\mathcal{D}}$ that contain $p$ in their domain, which we denote by $\operatorname{Dom}(\Psi)$. Equivalently, $\mathcal{O}_{\mathcal{D}}(p)$ is the set of points that can be joined to $p$ by a piecewise smooth curve tangent to $\mathcal{D}$. By the classical result of Chow and Rashevskii applied to the connected manifold $U$ and the distribution $\mathcal{D}|_U$, any two points of $U$ can be joined by a piecewise smooth curve tangent to $\mathcal{D}|_U$. Hence:
\begin{equation}
\label{eq:Uaccessibilityorbit}
U\subseteq\mathcal{O}_{\mathcal{D}}(p).
\end{equation}

We claim that $\mathcal{O}_{\mathcal{D}}(p)$ is open in $M$. Let $q\in\mathcal{O}_{\mathcal{D}}(p)$. By definition, there exists $\Psi\in\mathcal{P}_{\mathcal{D}}$ such that:
\begin{equation*}
p\in\operatorname{Dom}(\Psi), \qquad \Psi(p)=q.
\end{equation*}

Since $\operatorname{Dom}(\Psi)$ and $U$ are open neighborhoods of $p$, we may choose an open neighborhood $V$ of $p$ such that $V\subseteq U\cap\operatorname{Dom}(\Psi)$. The set $\Psi(V)$ is then an open neighborhood of $q$, because $\Psi$ is a local diffeomorphism. On the other hand, every $m\in V$ belongs to $\mathcal{O}_{\mathcal{D}}(p)$ by Equation~\eqref{eq:Uaccessibilityorbit}, and applying $\Psi$ shows that $\Psi(m)$ is in the orbit of $m$. Hence, by composition it follows that $\Psi(m)$ is in the orbit of $p$, that is $\Psi(m) \in \mathcal{O}_{\mathcal{D}}(p)$. Thus $\Psi(V)$ is an open neighborhood of $q$ contained in $\mathcal{O}_{\mathcal{D}}(p)$, proving that $\mathcal{O}_{\mathcal{D}}(p)$ is open.\medskip

Equation~\eqref{eq:dmuReeb} now implies that $X(\mu)=0$ for every local section $X$ of $\mathcal{D}$. Hence $\mu$ is preserved by every local flow map $\Phi^X_t$ with $X$ tangent to $\mathcal{D}$, and therefore it is also preserved by every element of $\mathcal{P}_{\mathcal{D}}$. Since $\alpha(p)\neq 0$ and $\alpha\mu\equiv0$, we have $\mu(p)=0$. Consequently $\mu=0$ on $\mathcal{O}_{\mathcal{D}}(p)$. Since $\mathscr{L}_\xi\zeta=0$, the flow $\Phi_t$ preserves $\mathcal{D}$. It follows that conjugation by $\Phi_t$ preserves the pseudogroup associated with $\mathcal{D}$:
\begin{equation*}
\Phi_t\circ\Psi\circ\Phi_{-t} \in \mathcal{P}_{\mathcal{D}}
\end{equation*}

whenever $\Psi\in\mathcal{P}_{\mathcal{D}}$ and the composition is defined. Consequently, the global flow $\Phi_t$ of $\xi$ maps $\mathcal{D}$-orbits to $\mathcal{D}$-orbits. More precisely:
\begin{equation}
\label{eq:Reebmapsorbits}
\Phi_t (\mathcal{O}_{\mathcal{D}}(m) ) = \mathcal{O}_{\mathcal{D}} (\Phi_t(m) )
\end{equation}

for every $m\in M$ and every $t\in\mathbb{R}$. On the other hand, since $\xi(\alpha)=0$, we have $\alpha(\Phi_t(p))=\alpha(p)\neq 0$ for every $t\in\mathbb{R}$. Therefore, the curve:
\begin{equation*}
s\mapsto\Phi_s(p), \qquad s\in[\min\{0,t\},\max\{0,t\}]
\end{equation*}

is contained in the subset $\{\alpha\neq 0\}\subset M$. Since it starts at $p$, it is contained in its connected component $U$. Hence:
\begin{equation*}
\Phi_t(p)\in U\subseteq\mathcal{O}_{\mathcal{D}}(p)
\end{equation*}

and therefore:
\begin{equation*}
\mathcal{O}_{\mathcal{D}}(\Phi_t(p))=\mathcal{O}_{\mathcal{D}}(p).
\end{equation*}

Combining this with Equation~\eqref{eq:Reebmapsorbits}, we obtain:
\begin{equation}
\label{eq:orbitReebinvariant}
\Phi_t\bigl(\mathcal{O}_{\mathcal{D}}(p)\bigr)=\mathcal{O}_{\mathcal{D}}(p)
\end{equation}

for every $t\in\mathbb{R}$.\medskip

Consider now the complement:
\begin{equation*}
C:=M\setminus\mathcal{O}_{\mathcal{D}}(p).
\end{equation*}

We observe that the set $C$ is invariant under every local flow of a local section of $\mathcal{D}$. Indeed, if $q\in C$ and $\Phi^X_s(q)$ belonged to $\mathcal{O}_{\mathcal{D}}(p)$, then applying the inverse local flow $\Phi^X_{-s}$ would imply that $q\in\mathcal{O}_{\mathcal{D}}(p)$, which is a contradiction. Equation~\eqref{eq:orbitReebinvariant} similarly implies that $C$ is invariant under the global characteristic vector field flow. We claim that $C$ is open. Let $q\in C$, and choose local sections $X_1,X_2$ of $\mathcal{D}$ which form a basis of $\mathcal{D}$ on a neighborhood of $q$. For sufficiently small $(s_1,s_2,t)\in\mathbb{R}^3$, define:
\begin{equation*}
\Theta(s_1,s_2,t) := \Phi_t\circ \Phi^{X_2}_{s_2}\circ \Phi^{X_1}_{s_1}(q).
\end{equation*}

By the flow invariance of $C$, the image of $\Theta$ is contained in $C$. Furthermore:
\begin{equation*}
\mathrm{d}\Theta_{(0,0,0)}(a,b,c) = a X_1(q) + b X_2(q) + c \xi(q).
\end{equation*}

Since $T_qM=\mathcal{D}_q\oplus\mathbb{R}\xi(q)$, the linear map $\mathrm{d}\Theta_{(0,0,0)}\colon\mathbb{R}^3\to T_qM$ is an isomorphism. The inverse function theorem therefore implies that the image of $\Theta$ contains an open neighborhood of $q$. This neighborhood is contained in $C$, and hence $C$ is open. Thus both $\mathcal{O}_{\mathcal{D}}(p)$ and its complement $C$ are open. Since $M$ is connected and $\mathcal{O}_{\mathcal{D}}(p)$ is nonempty, we conclude that $C$ is empty and $\mathcal{O}_{\mathcal{D}}(p)=M$, which immediately implies that $\mu=0$ everywhere on $M$. Hence, we have proven that if $\alpha$ is not everywhere vanishing, then $\mu = 0$. Since the complementary case requires that $\alpha$ is everywhere vanishing, we conclude.

For a trans-Sasakian manifold we have:
\begin{equation*}
\nabla^g_X\xi = -\alpha\varphi(X) + \mu\bigl(X-\zeta(X)\xi\bigr).
\end{equation*}

Setting $X=\xi$ and using $\varphi(\xi)=0$ and $\zeta(\xi)=1$, we obtain $\nabla^g_\xi\xi=0$. Since $\xi$ has unit length, its integral curves are unit-speed geodesics. The completeness of $g$ implies that these geodesics are defined on all of $\mathbb{R}$. Hence the vector field $\xi$ is complete, and the conclusion follows from Theorem~\ref{thm:completeReebnogo}.

\label{ex:spin-counterexample-neg}
Let $M:=\{z=x+iy\in \mathbb{C}\mid |z|< \tfrac{1}{2}\}$ and equip it with the Euclidean metric $g_{\mathrm{eucl}}$ and its standard spin structure, whose complex spinor bundle we denote by $\Sigma M$. We set $e_1 := \tfrac{\partial}{\partial x}$ and $e_2 := \tfrac{\partial}{\partial y}$ and consider the unit and $\nabla$-parallel spinor $\varphi_1$ such that $e_1 \cdot e_2 \cdot \varphi_1 = i \varphi_1$ and define $\varphi_2 := e_1 \cdot \varphi_1$. Then $\{ \varphi_1, \varphi_2\}$ is a $\nabla$-parallel orthonormal frame of $\Sigma M$, with:
\begin{equation*}
e_1 \cdot \varphi_1 = \varphi_2,\qquad e_1 \cdot \varphi_2 = -\varphi_1, \qquad e_2 \cdot \varphi_1 = -i\varphi_2,\qquad e_2 \cdot \varphi_2 = -i\varphi_1.
\end{equation*}

Let $\sqrt{z}$ be the principal branch of the square root on $\mathbb{C} \setminus\{x\leq0,\, y=0\}$. We define:
\begin{equation*}
\psi := \sqrt{1-z}\, \varphi_1 + \sqrt{\overline z + i}\, \varphi_2, \qquad a(z) + ib(z):= \frac{1}{2\sqrt{1-z}\sqrt{\overline{z}+i}}
\end{equation*}

and compute the $\nabla$-derivative of $\psi$:
\begin{align*}
    \nabla_{e_1} \psi &= - \frac{1}{2 \sqrt{1-z}} \varphi_1 + \frac{1}{2 \sqrt{\overline z + i}} \varphi_2 = (a(z) + ib(z))\, e_1\cdot \psi,\\
    \nabla_{e_2}\psi &= - \frac{i}{2 \sqrt{1-z}} \varphi_1 - \frac{i}{2 \sqrt{\overline z + i}} \varphi_2 = (a(z) + ib(z))\, e_2\cdot \psi.
\end{align*}

Thus, $\psi$ is a complex generalized Killing spinor on the spin manifold $(M,g_{\mathrm{eucl}})$. Moreover:
\begin{equation*}
a(0) +ib(0) = \frac{1}{2\sqrt{i}}= \frac{\sqrt{i}}{2i} = \frac{1-i}{2\sqrt{2}}
\end{equation*}

and, consequently:
\begin{equation*}
a(0) b(0) = \left(\frac{1}{2\sqrt{2}}\right) \left(\frac{-1}{2\sqrt{2}}\right) = -\frac{1}{8}\neq 0.
\end{equation*}

This example contradicts~\cite[Lemma~3.4]{Grosse_Nakad_2015} in dimension two.

We have assumed that $c\neq0$. Taking $k=0$ in Equation (7) gives $\omega_2=\frac{1}{2c}\mathrm{d} b\wedge\omega_1$ and taking $k=0$ in Equation (8) gives $\omega_3=\frac{i}{2c}\mathrm{d} a\wedge\omega_2$. Finally, taking $k=1$ in Equation (7) gives $\omega_4=\frac{1}{2c}\mathrm{d} b\wedge\omega_3$. Substituting the first two expressions yields:
\begin{equation*}
\omega_4=\frac{i}{4c^2}\mathrm{d} b\wedge\mathrm{d} a\wedge\omega_2=\frac{i}{8c^3}\mathrm{d} b\wedge\mathrm{d} a\wedge\mathrm{d} b\wedge\omega_1=0.
\end{equation*}

Arguing by induction we conclude that $\omega_p=0$ for every $p\geq4$. In particular, $\omega_n=0$. However, for a positively oriented orthonormal frame $\{e_1,\ldots,e_n\}$ of $(M,g)$ we have:
\begin{equation*}
e_1\cdots e_n\cdot\psi=i^{-\frac{n+1}{2}}\psi
\end{equation*}

since the complexified volume element $\omega_\mathbb{C}$ acts as the identity in odd dimensions. Hence:
\begin{equation*}
\omega_n(e_1,\ldots,e_n)=\langlee_1\cdots e_n\cdot\psi,\psi\rangle=i^{-\frac{n+1}{2}}\left\lvert\psi\right\rvert^2\neq0
\end{equation*}

since $\psi$ has no zeros by Lemma 3.1(iv). Therefore, we get a contradiction and conclude that $ab=0$.

In this case the degree-four induction argument does not apply, but Equation (7) with $k=0$ gives $\mathrm{d} b\wedge\omega_1=2c\omega_2$. Let $\{e_1,e_2,e_3\}$ be a positively oriented orthonormal frame of $(M,g)$. In dimension three, the complexified volume element satisfies $e_1\cdot e_2\cdot e_3\cdot\psi=-\psi$. Hence:
\begin{equation*}
e_1\cdot e_2\cdot\psi=e_3\cdot\psi,\qquad e_2\cdot e_3\cdot\psi=e_1\cdot\psi,\qquad e_3\cdot e_1\cdot\psi=e_2\cdot\psi
\end{equation*}

and therefore:
\begin{equation*}
\omega_2(e_1,e_2)=\omega_1(e_3),\qquad \omega_2(e_2,e_3)=\omega_1(e_1),\qquad \omega_2(e_3,e_1)=\omega_1(e_2).
\end{equation*}

Using the above relations, and recalling the normalized convention for the wedge product, we obtain:
\begin{equation*}
(\omega_2\wedge\omega_1)(e_1,e_2,e_3)=\frac{1}{3}(\omega_1(e_1)^2+\omega_1(e_2)^2+\omega_1(e_3)^2).
\end{equation*}

We now prove that:
\begin{equation*}
\sum_{j=1}^3\omega_1(e_j)^2=-\left\lvert\psi\right\rvert^4.
\end{equation*}

Indeed, at the point $x$ we may identify the spinor fiber with $\mathbb{C}^2$ and choose the Clifford representation:
\begin{equation*}
e_1\cdot=\begin{pmatrix}
    0&1\\
    -1&0
\end{pmatrix},\qquad e_2\cdot=\begin{pmatrix}
    0&i\\
    i&0
\end{pmatrix},\qquad e_3\cdot=\begin{pmatrix}
    i&0\\
    0&-i
\end{pmatrix},
\end{equation*}

for which $e_j\cdot e_j\cdot=-\mathrm{Id}$ and $e_1\cdot e_2\cdot e_3\cdot =-\mathrm{Id}$. Writing $\psi=\binom{z_1}{z_2}$ and recalling that the Hermitian product $\langle\cdot,\cdot\rangle$ is linear in the first entry, we obtain:
\begin{equation*}
\omega_1(e_1)=z_2\overline{z}_1-z_1\overline{z}_2,\qquad \omega_1(e_2)=i(z_2\overline{z}_1+z_1\overline{z}_2),\qquad \omega_1(e_3)=i(\left\lvertz_1\right\rvert^2-\left\lvertz_2\right\rvert^2).
\end{equation*}

Therefore:
\begin{equation*}
\sum_{j=1}^3\omega_1(e_j)^2=-4\left\lvertz_1\right\rvert^2\left\lvertz_2\right\rvert^2-(\left\lvertz_1\right\rvert^2-\left\lvertz_2\right\rvert^2)^2=-(\left\lvertz_1\right\rvert^2+\left\lvertz_2\right\rvert^2)^2=-\left\lvert\psi\right\rvert^4.
\end{equation*}

Consequently:
\begin{equation*}
(\omega_2\wedge\omega_1)(e_1,e_2,e_3)=-\frac{1}{3}\left\lvert\psi\right\rvert^4\neq0,
\end{equation*}

since $\psi$ has no zeros by Lemma 3.1(iv), thus $\omega_2\wedge\omega_1\neq0$. Finally, wedging $\mathrm{d} b\wedge\omega_1=2c\omega_2$ with $\omega_1$, we obtain:
\begin{equation*}
0=\mathrm{d} b\wedge\omega_1\wedge\omega_1=2c\omega_2\wedge\omega_1,
\end{equation*}

which implies that $c=0$. Therefore, we get a contradiction and conclude that $ab=0$.
